  ('dlce', 'Department of Linguistic and Cultural Evolution', 'DLCE', '#17948a', 'ou_3237541'),
  ('evogen', 'Department of Evolutionary Genetics', 'EvoGen', '#8fa0b3', 'ou_1497672'),
  ('humor', 'Department of Human Origins', 'HumOr', '#e8c33e', 'ou_3482006'),
  ('primevo', 'Department of Primate Behavior and Evolution', 'PrimEvo', '#e2841e', 'ou_3367832'),
  ('ccp', 'Department of Comparative Cultural Psychology', 'CCP', '#a3a13a', 'ou_3040267')
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-theory-population-genetics', 'Population genetics', 'theory', 'The mathematical theory of how allele and genotype frequencies change over time under mutation, selection, drift, migration, and mating patterns — the formal backbone for interpreting ancient and modern genomic variation.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-theory-population-genetics"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['allele frequency','evolutionary genetics','quantitative theory']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-theory-human-evolution', 'Human evolution', 'theory', 'The broad evolutionary framework describing the origin and diversification of Homo sapiens and related hominins, which archaeogenetics tests directly against ancient genomic evidence.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-theory-human-evolution"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['hominin','phylogeny','origins']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-theory-demographic-history', 'Demographic history', 'theory', 'Reconstruction of past population sizes, splits, contractions, and expansions from patterns of genetic variation, used to infer the lived history behind a genome.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-theory-demographic-history"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['population size','bottleneck','expansion']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-theory-selection', 'Selection', 'theory', 'The theory of differential reproductive success driving allele frequency change, distinguished in genomic data from drift by characteristic signatures (e.g. reduced diversity, extended haplotypes) around a selected locus.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-theory-selection"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['natural selection','adaptation','selective sweep']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-theory-admixture', 'Admixture', 'theory', 'The theory and statistical modeling of gene flow between previously separated populations (including between Homo sapiens and archaic hominins), leaving detectable mosaic ancestry patterns in descendant genomes.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-theory-admixture"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['gene flow','hybridization','ancestry']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-theory-migration-models', 'Migration models', 'theory', 'Formal models of how populations move and exchange migrants across space and time, used to fit genomic data to candidate routes and rates of human dispersal.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-theory-migration-models"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['dispersal','gene flow','spatial modeling']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-domain-ancient-dna', 'Ancient DNA', 'domain', 'DNA recovered from archaeological and paleontological remains (bone, teeth, sediment), typically degraded and contaminated, requiring specialized extraction and authentication methods.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-domain-ancient-dna"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['aDNA','degraded DNA','archaeology']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-domain-genomes', 'Genomes', 'domain', 'Complete or partial genomic sequences — ancient and modern — that serve as the department''s core empirical material.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-domain-genomes"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['genomics','sequencing data']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-domain-archaic-admixture', 'Archaic admixture', 'domain', 'The genomic legacy of interbreeding between anatomically modern humans and archaic hominins such as Neanderthals and Denisovans.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-domain-archaic-admixture"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Neanderthal','Denisovan','introgression']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-domain-pathogens', 'Pathogens', 'domain', 'Ancient microbial and viral DNA recovered alongside or from host remains, used to track the evolutionary history of infectious disease and past epidemics.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-domain-pathogens"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['paleopathogenomics','disease history']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-domain-domestication', 'Domestication', 'domain', 'The genomic study of how plant and animal species were brought under human management, tracing selective and demographic signatures of domestication events.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-domain-domestication"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['agriculture','animal husbandry','plant genomics']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-domain-paleodemography', 'Paleodemography', 'domain', 'The reconstruction of past population structure, size, and vital rates from ancient genomic and skeletal evidence.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-domain-paleodemography"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['ancient populations','demography']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-domain-medieval-and-historical-populations', 'Medieval and historical-period populations', 'domain', 'Genome-wide ancient DNA from Common Era populations — early medieval Britain, Bronze Age-to-Iron Age Aegean, and other historically documented societies — as distinct empirical material from DAG''s Paleolithic/Pleistocene work, using written and archaeological record alongside the genomic signal.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-domain-medieval-and-historical-populations"}'::jsonb, '{"source": "curator-drafted; grounded in Gretzinger et al. 2022 Nature (Anglo-Saxon migration) and Skourtanioti et al. 2023 Nature Ecology & Evolution (prehistoric Aegean admixture) — eva.mpg.de/archaeogenetics/", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['medieval Europe','historical genomics','Common Era']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-method-shotgun-sequencing', 'Shotgun sequencing', 'method', 'Untargeted high-throughput sequencing of all DNA fragments in a sample, the default approach for ancient DNA where library content is otherwise unpredictable.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-method-shotgun-sequencing"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['NGS','sequencing']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-method-capture-enrichment', 'Capture enrichment', 'method', 'A hybridization-based technique that selectively enriches a sequencing library for target genomic regions, used to boost coverage of informative loci from low-yield ancient samples.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-method-capture-enrichment"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['target enrichment','hybridization capture']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-method-bioinformatics', 'Bioinformatics', 'method', 'Computational pipelines for read alignment, quality filtering, damage-pattern authentication, and variant calling that turn raw ancient-DNA sequence data into analyzable genotypes.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-method-bioinformatics"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['pipelines','computational biology']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-method-phylogenetics', 'Phylogenetics', 'method', 'Methods for reconstructing evolutionary relationships and divergence times among lineages from genetic sequence data.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-method-phylogenetics"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['tree building','divergence dating']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-method-coalescent-modeling', 'Coalescent modeling', 'method', 'A statistical framework that models how gene lineages sampled today trace back to shared common ancestors, used to infer demographic history and divergence times from genomic variation.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-method-coalescent-modeling"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['coalescent theory','demographic inference']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-method-haplotype-analysis', 'Haplotype analysis', 'method', 'Analysis of blocks of linked genetic variants inherited together, used to detect admixture, selection, and fine-scale population structure.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-method-haplotype-analysis"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['linkage','haplotype blocks']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-method-identity-by-descent-analysis', 'Identity-by-descent (IBD) segment analysis', 'method', 'Detection of chromosome segments shared between individuals because they were inherited, unbroken by recombination, from a recent common ancestor — the basis for reconstructing kinship and fine-scale population structure directly from genomes, including low-coverage ancient ones once genotype probabilities are imputed.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-method-identity-by-descent-analysis"}'::jsonb, '{"source": "curator-drafted; grounded in Ringbauer, Huang, Akbari, Mallick, Olalde, Patterson & Reich (2024, Nature Genetics 56:143-151, doi:10.1038/s41588-023-01582-w)", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['IBD','kinship inference','imputation']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-topic-neanderthal-admixture', 'Neanderthal admixture', 'topic', 'Open questions about the timing, geography, and functional consequences of interbreeding between modern humans and Neanderthals, whose genomic traces persist in most present-day non-African populations.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-topic-neanderthal-admixture"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Neanderthal','introgression']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-topic-population-structure', 'Population structure', 'topic', 'How genetic variation is organized across geography and social groups, and how that structure has changed through prehistory and history.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-topic-population-structure"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['genetic structure','geography']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-topic-migration-waves', 'Migration waves', 'topic', 'Reconstructing successive episodes of human movement and resettlement — e.g. Out-of-Africa dispersals, Neolithic farming expansions, steppe migrations — from ancient genomic transects.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-topic-migration-waves"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['dispersal','prehistory']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-topic-selection-signals', 'Selection signals', 'topic', 'Genomic signatures left by natural selection acting on specific loci (e.g. lactase persistence, high-altitude adaptation), and how to distinguish them reliably from drift.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-topic-selection-signals"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['adaptation','selective sweep']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-topic-genetic-drift', 'Genetic drift', 'topic', 'The role of random allele-frequency change, especially in small or bottlenecked populations, in shaping the genomic record independent of selection.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-topic-genetic-drift", "conceptBaseId": "OE-CONCEPT-bio-core-drift"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['drift','stochastic processes']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-topic-plague-genomics', 'Plague genomics and the source of the Black Death', 'topic', 'Reconstructing the phylogeny and geographic origin of Yersinia pestis pandemics directly from ancient DNA recovered from burials — DAG''s flagship pathogen-genomics result identified 14th-century Central Asia, not the Black Sea/Crimea, as the source of the strain ancestral to the Black Death''s explosive ''Big Bang'' diversification.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-topic-plague-genomics"}'::jsonb, '{"source": "curator-drafted; grounded in Spyrou, Musralina, Gnecchi Ruscone, Kocher, Borbone, Khartanovich, Buzhilova, Djansugurova, Bos, Kühnert, Haak, Slavin & Krause (2022, Nature 606:718-724, doi:10.1038/s41586-022-04800-3, ''The source of the Black Death in fourteenth-century central Eurasia'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Yersinia pestis','Black Death','paleoepidemiology','medieval Europe']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-topic-treponemal-disease-origins', 'Origins of treponemal disease (syphilis)', 'topic', 'The long-running debate over whether syphilis and its relatives (the treponemal diseases) originated in the Old World or the New World, addressed directly with ancient Treponema pallidum genomes rather than historical inference alone.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-topic-treponemal-disease-origins"}'::jsonb, '{"source": "curator-drafted; grounded in Barquera, Sitter, Kirkpatrick, Ramirez, Kocher, Spyrou, Herbig, Krause & Bos (2024/2025, Nature 640:186-193, doi:10.1038/s41586-024-08515-5, ''Ancient genomes reveal a deep history of Treponema pallidum in the Americas''), which found treponemal disease established in the Americas centuries before European contact", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Treponema pallidum','syphilis','Americas','disease origins']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-topic-ancient-leprosy', 'Ancient leprosy (Hansen''s disease) in the Americas', 'topic', 'Reconstructing the deep history of leprosy-causing bacteria — both the well-known Mycobacterium leprae and the rarer M. lepromatosis — from ancient genomes, distinguishing independently established Old World and New World histories of the disease.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-topic-ancient-leprosy"}'::jsonb, '{"source": "curator-drafted; grounded in Ramirez, Sitter, Översti, Herrera-Soto, Kirkpatrick, Nores & Bos (2025, Nature Ecology & Evolution 9:1685-1693, doi:10.1038/s41559-025-02771-y, ''4,000-year-old Mycobacterium lepromatosis genomes from Chile reveal long establishment of Hansen''s disease in the Americas'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Mycobacterium leprae','Mycobacterium lepromatosis','Hansen''s disease','Americas']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-topic-anglo-saxon-migration', 'The Anglo-Saxon migration and early English ancestry', 'topic', 'Genome-wide ancient DNA testing how much of early medieval England''s population descends from Continental migrants versus existing Romano-British populations, and whether that migration was sex-biased — the first large-scale genomic study of this historically documented but genomically under-tested migration.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-topic-anglo-saxon-migration"}'::jsonb, '{"source": "curator-drafted; grounded in Gretzinger, Sayer, Justeau, Altena, Pala, Dulias, Edwards, ... Haak, Bos, ... Reich, Krause & Schiffels (2022, Nature 610:112-119, doi:10.1038/s41586-022-05247-2, ''The Anglo-Saxon migration and the formation of the early English gene pool''), finding up to ~76% Continental ancestry in some early medieval English communities plus detectable sex-biased migration", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Anglo-Saxon','medieval England','migration genomics']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-topic-bronze-age-aegean-admixture', 'Bronze Age Aegean admixture and endogamy', 'topic', 'Fine-grained ancient-DNA reconstruction of population history across Neolithic-to-Iron-Age Crete, mainland Greece, and the Aegean islands, tracing when Anatolian-derived and later steppe-derived ancestry arrived in different parts of the region, and detecting localized endogamy (mating within a small, closed community).', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-topic-bronze-age-aegean-admixture"}'::jsonb, '{"source": "curator-drafted; grounded in Skourtanioti, Ringbauer, Gnecchi Ruscone, Bianco, ... Krause, Jeong & Stockhammer (2023, Nature Ecology & Evolution 7:290-303, doi:10.1038/s41559-022-01952-3, ''Ancient DNA reveals admixture history and endogamy in the prehistoric Aegean'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Aegean','Bronze Age','endogamy','Anatolia']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-topic-kinship-and-pedigree-reconstruction', 'Kinship and pedigree reconstruction from ancient DNA', 'topic', 'Using genome-wide identity-by-descent signal to reconstruct biological relatedness — parent-offspring, sibling, cousin, and more distant kin ties — among individuals buried at the same site, revealing social and family structure that skeletal evidence alone cannot show.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-topic-kinship-and-pedigree-reconstruction"}'::jsonb, '{"source": "curator-drafted; grounded in Harald Ringbauer''s Haplo Group (current DAG research group) and its ancIBD method, and applied directly in this dataset''s own fieldsite-issyk-kurgan (Ghalichi, Rohrlach, Gnecchi-Ruscone, Haak & Krause 2026, Science Advances, doi:10.1126/sciadv.aef0108, elite dynastic-lineage reconstruction — first-author attribution corrected 2026-09-03 via live Crossref verification, was previously misattributed to Haak)", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['kinship','pedigree','burial archaeology']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-scicomm-ancestral-remains-and-repatriation', 'Ancient DNA from human ancestral remains', 'scicomm-sensitivity', 'The field has moved, following documented controversies (including cases at MPI-EVA and peer institutions), toward requiring community consultation, consent, and benefit-sharing before ancient-DNA research proceeds on ancestral remains — a 2021 field-wide guidance document (Wagner et al., ''Fostering Responsible Research on Ancient Human Remains,'' co-authored by MPI-EVA researchers) sets out the current expected practice.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-scicomm-ancestral-remains-and-repatriation"}'::jsonb, '{"source": "curator-drafted; grounded in Wagner et al. 2020/2021 ''Fostering Responsible Research on Ancient Human Remains'' (co-authored by MPI-EVA-affiliated researchers) and documented ancient-DNA consent controversies", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['ancient DNA','human remains','repatriation','informed consent','indigenous rights']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-scicomm-race-and-ancestry-framing', 'Population genetics, ancestry, and ''race'' framing', 'scicomm-sensitivity', 'Population genetics is one of the fields most reliably misappropriated to lend false scientific authority to essentialist race concepts, even though the underlying findings (clinal variation, extensive admixture, no genetic basis for discrete race categories) argue directly against that reading.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-scicomm-race-and-ancestry-framing"}'::jsonb, '{"source": "curator-drafted; grounded in documented field-wide concern (e.g. AAPA statement on race and racism, 2019) about population-genetics misappropriation for race-essentialist claims", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['population genetics','race and genetics','ancestry testing','public misappropriation']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dag-scicomm-neanderthal-dna-popular-narratives', '''Percent Neanderthal'' popular narratives', 'scicomm-sensitivity', 'Same underlying oversimplification pattern documented under evogen-scicomm-archaic-introgression-headlines, arising here from the demographic-modeling side rather than the functional-genomics side.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "dag-scicomm-neanderthal-dna-popular-narratives"}'::jsonb, '{"source": "curator-drafted; grounded in documented public-communication critiques of consumer ancestry-testing narratives around archaic introgression", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['archaic introgression','public narratives','media coverage']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-theory-cultural-evolution', 'Cultural evolution', 'theory', 'The theory that culturally transmitted information (skills, beliefs, practices) changes over time through processes analogous to biological evolution — variation, selection, and inheritance via social learning.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-theory-cultural-evolution"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cultural transmission','social learning']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-theory-social-learning', 'Social learning', 'theory', 'The study of how individuals acquire information and behavior by observing or interacting with others, rather than through individual trial-and-error.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-theory-social-learning", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-learning"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['imitation','teaching','learning strategies']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-theory-cumulative-culture', 'Cumulative culture', 'theory', 'The theory that human culture can accumulate complexity across generations beyond what any single individual could invent alone, via high-fidelity social transmission.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-theory-cumulative-culture", "conceptBaseId": "OE-SANDBOX-CONCEPT-000019"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['ratchet effect','innovation']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-theory-life-history-theory', 'Life history theory', 'theory', 'An evolutionary framework explaining how organisms allocate limited resources between growth, reproduction, and survival across the lifespan, shaped by ecological trade-offs.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-theory-life-history-theory"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['growth','reproduction','trade-offs']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-theory-cooperation', 'Cooperation', 'theory', 'Theoretical frameworks explaining why individuals incur costs to benefit others, spanning kin selection, reciprocity, and group-level mechanisms.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-theory-cooperation", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-cooperation"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['prosociality','collective action']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-theory-kin-selection', 'Kin selection', 'theory', 'The theory that helping behavior can evolve when it benefits genetic relatives, formalized by Hamilton''s rule relating relatedness, cost, and benefit.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-theory-kin-selection"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['inclusive fitness','Hamilton''s rule']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-theory-reciprocity', 'Reciprocity', 'theory', 'The theory that cooperation between non-relatives can be sustained through repeated exchange of favors, including direct, indirect, and generalized reciprocity.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-theory-reciprocity"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['reciprocal altruism','exchange']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-theory-cultural-transmission', 'Cultural transmission', 'theory', 'Formal models of how cultural traits are passed between individuals — vertically (parent to offspring), horizontally (peer to peer), or obliquely — and with what fidelity.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-theory-cultural-transmission"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['transmission pathways','dual inheritance']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-theory-niche-construction', 'Niche construction', 'theory', 'The theory that organisms actively modify their environments in ways that alter the selection pressures acting on themselves and other species, feeding back into evolution.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-theory-niche-construction", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-niche-construction"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['ecological inheritance','environmental modification']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-theory-behavioral-ecology', 'Behavioral ecology', 'theory', 'The study of how behavior is shaped by ecological and social conditions to maximize fitness, using cost-benefit and optimality reasoning.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-theory-behavioral-ecology"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['optimal foraging','adaptation']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-theory-evolutionary-anthropology', 'Evolutionary anthropology', 'theory', 'The broad interdisciplinary field applying evolutionary theory to human biology, behavior, and culture, integrating ecology, genetics, and ethnography.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-theory-evolutionary-anthropology"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['human evolution','interdisciplinary']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-theory-teaching', 'Teaching', 'theory', 'The study of costly, other-directed behavior that actively facilitates another individual''s learning — theorized as one evolved social-learning strategy among several, distinguished from imitation or observation by the cost it imposes on the teacher and reserved, in practice, for information a learner is unlikely to infer on their own.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-theory-teaching", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-teaching"}'::jsonb, '{"source": "curator-drafted; grounded in Boyette & Hewlett (2018, Review of Philosophy and Psychology, ''Teaching in Hunter-Gatherers'') and the functional definition of teaching from Caro & Hauser (1992)", "status": "draft", "created": "2026-09-02", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['directed transmission','hunter-gatherers','middle childhood']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-theory-gene-culture-coevolution', 'Gene-culture coevolution', 'theory', 'The theory that genetic and cultural evolution are coupled dynamical processes, each altering the selective conditions the other operates under — e.g. culturally transmitted subsistence practices (like dairying) creating the selection pressure behind a later genetic change (like lactase persistence), or population size and demographic history jointly shaping how much cultural complexity a population can sustain.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-theory-gene-culture-coevolution"}'::jsonb, '{"source": "curator-drafted; grounded in TICE lab''s stated research focus (Fogarty staff profile, eva.mpg.de) and Fogarty, Wakano, Feldman & Aoki (2017, Human Nature, doi:10.1007/s12110-016-9275-6) and Fogarty & Creanza (2017, Phil. Trans. R. Soc. B, doi:10.1098/rstb.2016.0428)", "status": "draft", "created": "2026-09-02", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['dual inheritance','cultural niche construction','population size','demography']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-domain-hunter-gatherers', 'Hunter-gatherers', 'domain', 'Contemporary and historically documented foraging societies, a key comparative population for reconstructing ancestral human social and subsistence patterns.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-domain-hunter-gatherers"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['foragers','small-scale societies']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-domain-subsistence-strategies', 'Subsistence strategies', 'domain', 'The range of ways human groups obtain food and resources — foraging, pastoralism, horticulture, agriculture — and how these shape social organization.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-domain-subsistence-strategies"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['food acquisition','economy']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-domain-foraging', 'Foraging', 'domain', 'The behavior and decision-making involved in searching for and acquiring wild food resources, studied both ethnographically and through optimal-foraging models.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-domain-foraging"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['food search','resource acquisition']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-domain-mobility-patterns', 'Mobility patterns', 'domain', 'How and why groups move across landscapes — residential and logistical mobility — and its consequences for social structure and resource use.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-domain-mobility-patterns"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['settlement patterns','movement']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-domain-demography', 'Demography', 'domain', 'The study of population size, structure, fertility, and mortality in small-scale and traditional societies.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-domain-demography"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['population dynamics','fertility','mortality']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-domain-ritual', 'Ritual', 'domain', 'Formalized, repeated social practices with symbolic content, studied for their role in group cohesion, signaling, and cultural transmission.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-domain-ritual"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['symbolic behavior','ceremony']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-domain-kinship-systems', 'Kinship systems', 'domain', 'The culturally variable rules and categories that define family relationships, descent, and marriage, and their consequences for cooperation and resource sharing.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-domain-kinship-systems"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['descent','marriage','family structure']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-domain-material-culture', 'Material culture', 'domain', 'The physical objects, tools, and artifacts a society produces and uses, studied as evidence of behavior, technology, and cultural transmission.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-domain-material-culture"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['artifacts','technology']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-domain-innovation', 'Innovation', 'domain', 'The generation of novel behaviors, tools, or ideas within a population, and the social conditions that favor or suppress it.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-domain-innovation", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-innovation"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['invention','creativity']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-domain-traditions', 'Traditions', 'domain', 'Behavioral or cultural practices maintained across generations through social learning, studied for their stability, variation, and transmission mechanisms.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-domain-traditions"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cultural practices','continuity']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-domain-child-development', 'Child development', 'domain', 'The biocultural study of how children grow, learn, and are cared for — integrating developmental psychology, life history theory, and direct ethnographic observation (focal follows, behavior coding) of everyday learning environments in small-scale societies.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-domain-child-development"}'::jsonb, '{"source": "curator-drafted; grounded in Adam Boyette''s HBEC research program (Culture, Cooperation and Child Development Research Group) on childhood learning among Aka, Ngandu, and BaYaka communities of the Congo Basin", "status": "draft", "created": "2026-09-02", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['childhood','developmental niche','focal-follow methods']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-domain-arctic-indigenous-subsistence-economy', 'Arctic Indigenous subsistence economy', 'domain', 'Inuit and other Arctic Indigenous foraging, hunting, and harvesting economies, studied for how they interact with an encroaching market/carbon economy — a real, current HBEC field program (the Sanguatsiniq project) distinct from the department''s Congo Basin and Pemba Island work.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-domain-arctic-indigenous-subsistence-economy"}'::jsonb, '{"source": "curator-drafted; grounded in Ready, Ross, Beheim & Parrott (2024, PNAS 121(32), doi:10.1073/pnas.2317686121, ''Indigenous food production in a carbon economy'') — eva.mpg.de/ecology/projects-and-research-groups/", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Inuit','Arctic','subsistence economy','carbon economy']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-method-ethnography', 'Ethnography', 'method', 'Long-term, in-depth qualitative fieldwork documenting the practices, beliefs, and social organization of a community, typically through participant observation.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-method-ethnography"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['fieldwork','qualitative research']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-method-field-experiments', 'Field experiments', 'method', 'Controlled behavioral experiments (e.g. economic games) conducted in situ with real communities, combining experimental control with ecological validity.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-method-field-experiments"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['economic games','in situ testing']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-method-agent-based-modeling', 'Agent-based modeling', 'method', 'Computational simulation of populations of interacting individuals following simple rules, used to test how macro-level cultural or social patterns can emerge from micro-level behavior.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-method-agent-based-modeling"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['simulation','computational modeling']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-method-comparative-methods', 'Comparative methods', 'method', 'Systematic cross-population or cross-species comparison used to test hypotheses about the causes of behavioral or cultural variation.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-method-comparative-methods"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cross-cultural comparison','cross-species comparison']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-method-bayesian-inference', 'Bayesian inference', 'method', 'A statistical framework updating probability estimates for hypotheses as new data arrive, widely used for parameter estimation in behavioral and demographic models.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-method-bayesian-inference"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['statistics','probabilistic modeling']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-method-gis', 'GIS', 'method', 'Geographic Information Systems used to map, analyze, and model spatial patterns in mobility, resource use, and settlement.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-method-gis"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['spatial analysis','mapping']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-method-cross-cultural-databases', 'Cross-cultural databases', 'method', 'Large structured datasets coding cultural, social, and ecological variables across many societies, used for statistical cross-cultural comparison (e.g. eHRAF-style resources).', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-method-cross-cultural-databases"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['ethnographic databases','coded variables']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-method-phylogenetic-comparative-methods', 'Phylogenetic comparative methods', 'method', 'Statistical techniques that account for shared ancestry between populations or species when testing hypotheses about trait correlations.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-method-phylogenetic-comparative-methods"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['phylogenetics','non-independence']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-method-causal-inference-modeling', 'Causal inference modeling for cross-cultural comparison', 'method', 'A generative, DAG-based (directed acyclic graph) causal-modeling framework with explicit graphical criteria for deciding when and how findings can be projected or compared across populations, and for formally representing measurement (in)equivalence between societies — distinct from applying a phylogenetic correction, this addresses whether the same construct is even being measured the same way in different cultural contexts.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-method-causal-inference-modeling"}'::jsonb, '{"source": "curator-drafted; grounded in Deffner, Rohrer & McElreath (2022, Advances in Methods and Practices in Psychological Science 5(3):1-18, doi:10.1177/25152459221106366, ''A Causal Framework for Cross-Cultural Generalizability'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['causal inference','DAGs','measurement equivalence','cross-cultural generalizability']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-method-theory-to-data-computational-workflow', 'Theory-to-data computational workflow', 'method', 'A modeling practice that derives the statistical model used to analyze real field or experimental data directly and transparently from formal cultural-evolution theory, rather than choosing an off-the-shelf statistical test and interpreting it as a theory test after the fact — intended to close a long-standing gap between abstract cultural-evolution models and empirical analysis.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-method-theory-to-data-computational-workflow"}'::jsonb, '{"source": "curator-drafted; grounded in Deffner, Fedorova & Andrews & McElreath (2024, PNAS 121(48), doi:10.1073/pnas.2322887121, ''Bridging theory and data: A computational workflow for cultural evolution'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['computational modeling','statistical workflow','theory-data gap']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-topic-cooperation', 'Cooperation', 'topic', 'Open questions about the mechanisms and conditions that sustain cooperative behavior in human groups, from small-scale forager bands to large institutions.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-topic-cooperation", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-cooperation"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['prosociality']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-topic-fairness', 'Fairness', 'topic', 'Cross-cultural and evolutionary study of how norms of fair distribution and exchange emerge, vary, and are enforced.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-topic-fairness"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['equity','distribution norms']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-topic-punishment', 'Punishment', 'topic', 'The study of costly sanctioning of norm violators, including third-party and altruistic punishment, and its role in sustaining cooperation.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-topic-punishment"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['norm enforcement','sanctioning']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-topic-partner-choice', 'Partner choice', 'topic', 'How individuals select, retain, and switch cooperative partners, and how this market-like dynamic shapes the evolution of cooperative behavior.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-topic-partner-choice"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['biological markets','social selection']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-topic-cultural-diversity', 'Cultural diversity', 'topic', 'The patterns, causes, and consequences of variation in beliefs, practices, and institutions across human societies.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-topic-cultural-diversity"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['variation','cross-cultural difference']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-topic-norms', 'Norms', 'topic', 'The origins, transmission, and enforcement of shared behavioral expectations within a group.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-topic-norms", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-norms"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['social norms','normativity']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-topic-institutions', 'Institutions', 'topic', 'The study of formal and informal rule systems that structure collective action and resource governance in human groups.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-topic-institutions", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-institutions"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['governance','rule systems']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-topic-inequality', 'Inequality', 'topic', 'The evolutionary and ecological origins of resource and status disparities within and between human groups.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-topic-inequality"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['status','resource disparity']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-topic-childrens-play', 'Children''s play', 'topic', 'Cross-cultural and evolutionary study of play — including work-themed and object play — as a low-cost arena where children practice subsistence, social, and motor skills before those skills carry real consequences; a major share of middle childhood''s activity budget in small-scale societies.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-topic-childrens-play"}'::jsonb, '{"source": "curator-drafted; grounded in Lew-Levy & Boyette (2018, Human Nature) and Boyette (2016, Child Development)", "status": "draft", "created": "2026-09-02", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['practice','skill acquisition','middle childhood']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-topic-autonomy-socialization', 'Socialization of autonomy', 'topic', 'How cultural values of personal autonomy and egalitarianism are transmitted to children in practice — for example through task assignment rather than command, and adults'' consistent respect for a child''s choice to participate, decline, or leave a task.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-topic-autonomy-socialization"}'::jsonb, '{"source": "curator-drafted; grounded in Boyette & Hewlett (2017, Human Nature) and Boyette & Lew-Levy (in press, Ethos, ''The socialization of cooperative autonomy among BaYaka foragers'')", "status": "draft", "created": "2026-09-02", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['egalitarianism','task assignment','values transmission']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-topic-parochial-altruism', 'Parochial altruism and perceived inequality', 'topic', 'Whether in-group-favoring, out-group-costly cooperative behavior (''parochial altruism'') is driven mainly by group identity itself or by perceived economic need and inequality — ethnographic, social-network, and economic-game data from two multi-ethnic Colombian communities found perceived group-based economic need explains more of the pattern than identity alone, with high variability both between communities and between individuals.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-topic-parochial-altruism"}'::jsonb, '{"source": "curator-drafted; grounded in Ross & Pisor (2024/2025, Evolutionary Human Sciences 7, doi:10.1017/ehs.2024.43, ''Perceived inequality and variability in the expression of parochial altruism'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['parochial altruism','in-group favoritism','inequality','economic games']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-topic-cross-cultural-generalizability', 'Cross-cultural generalizability', 'topic', 'The open methodological question of when a finding from one society can be legitimately compared, pooled, or generalized to another — whether the same construct was actually measured the same way across cultural contexts, not just whether the raw scores differ.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-topic-cross-cultural-generalizability"}'::jsonb, '{"source": "curator-drafted; grounded in Deffner, Rohrer & McElreath (2022, Advances in Methods and Practices in Psychological Science 5(3):1-18, doi:10.1177/25152459221106366)", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['generalizability','measurement equivalence','methodology']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-scicomm-fieldwork-with-small-scale-societies', 'Ethnographic fieldwork with hunter-gatherer and small-scale societies', 'scicomm-sensitivity', 'Contemporary practice in behavioral ecology and anthropology increasingly requires genuine reciprocity: community consultation on research questions, results shared back in accessible form, and tangible benefit to the community, not just publication credit to the researcher.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-scicomm-fieldwork-with-small-scale-societies"}'::jsonb, '{"source": "curator-drafted; grounded in documented critiques of extractive/parachute fieldwork and calls for reciprocal, consent-based ethnographic practice", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['fieldwork ethics','informed consent','reciprocity','hunter-gatherers']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('hbec-scicomm-living-fossil-framing', '''Living fossil'' / timeless-primitive framing of subsistence societies', 'scicomm-sensitivity', 'HBEC''s comparative use of subsistence-strategy data to understand human behavioral ecology is scientifically legitimate, but the popular shorthand for why that comparison is useful (''they show us how our ancestors lived'') misrepresents living communities as static relics rather than as people living contemporary lives shaped by their own history, including centuries of contact with surrounding states and economies.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "hbec-scicomm-living-fossil-framing"}'::jsonb, '{"source": "curator-drafted; grounded in the anthropological critique of denying coevalness (Fabian, 1983) as applied to popular framings of contemporary hunter-gatherer societies", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['living fossil framing','coevalness','othering','subsistence strategies']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-theory-language-evolution', 'Language evolution', 'theory', 'The study of how human language capacity and individual languages originated and change over time, spanning biological and cultural evolutionary processes.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-theory-language-evolution", "conceptBaseId": "OE-SANDBOX-CONCEPT-000003"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['origins of language','diachronic change']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-theory-cultural-evolution', 'Cultural evolution', 'theory', 'The theory that culturally transmitted traits, including linguistic and narrative traditions, change over generations through variation, selection, and inheritance.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-theory-cultural-evolution"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cultural transmission','descent with modification']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-theory-phylogenetics', 'Phylogenetics', 'theory', 'The theoretical framework treating languages and cultural traits as lineages that split and diversify, allowing tree-based methods borrowed from evolutionary biology.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-theory-phylogenetics"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['language trees','descent']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-theory-semantic-change', 'Semantic change', 'theory', 'The study of how word meanings shift over time, and what regularities (e.g. metaphor, narrowing, broadening) govern that shift across languages.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-theory-semantic-change"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['meaning shift','historical linguistics']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-theory-linguistic-typology', 'Linguistic typology', 'theory', 'The comparative study of structural diversity and universals across the world''s languages, classifying them by grammatical and phonological features.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-theory-linguistic-typology"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cross-linguistic comparison','universals']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-theory-social-learning', 'Social learning', 'theory', 'The study of how linguistic and cultural forms are transmitted through observation and interaction rather than innate specification alone.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-theory-social-learning"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['transmission mechanisms','learning biases']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-domain-language-families', 'Language families', 'domain', 'Groups of languages descended from a common ancestral language, the basic taxonomic unit for comparative and phylogenetic linguistics.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-domain-language-families"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['genealogical classification']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-domain-lexicons', 'Lexicons', 'domain', 'The vocabulary of a language, used as core comparative data for tracing relatedness, borrowing, and semantic change.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-domain-lexicons"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['vocabulary','word lists']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-domain-grammatical-structures', 'Grammatical structures', 'domain', 'The morphological and syntactic rules of languages, compared across families to identify typological patterns and constraints.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-domain-grammatical-structures"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['morphology','syntax']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-domain-oral-traditions', 'Oral traditions', 'domain', 'Narratives, histories, and knowledge transmitted verbally across generations, studied as a form of culturally evolving information.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-domain-oral-traditions"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['storytelling','verbal transmission']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-domain-folklore', 'Folklore', 'domain', 'Traditional stories, customs, and beliefs of a community, analyzed for patterns of variation, stability, and diffusion.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-domain-folklore"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['tales','tradition']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-domain-mythology', 'Mythology', 'domain', 'Bodies of traditional narrative, often explaining origins or cosmology, studied comparatively for shared and divergent motifs across cultures.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-domain-mythology"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['myth','narrative motifs']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-domain-cultural-traits', 'Cultural traits', 'domain', 'Discrete, codeable units of culture (practices, beliefs, technologies) used as the basic data for cultural phylogenetic and comparative analysis.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-domain-cultural-traits"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cultural units','coding schemes']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-domain-d-place', 'D-PLACE', 'domain', 'The Database of Places, Language, Culture and Environment — a large, curated cross-cultural dataset linking ethnographic, linguistic, environmental, and geographic data for over a thousand human societies, DLCE''s flagship comparative resource for testing macro-historical and cultural-evolutionary hypotheses at global scale.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-domain-d-place"}'::jsonb, '{"source": "curator-drafted; grounded in eva.mpg.de/linguistic-and-cultural-evolution/research/cool/ (Cultural Evolution) and D-PLACE''s own stated role in Chira et al. 2024''s 1,000+ mainland societies analysis", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cross-cultural database','ethnographic data','comparative dataset']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-domain-domesticated-dogs', 'Domesticated dogs', 'domain', 'Dogs and their human handlers across culturally and ecologically diverse societies, studied both as ethnographic data on human-animal relationships and as a comparative field-experimental population for social cognition, deliberately sampled beyond WEIRD contexts.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-domain-domesticated-dogs"}'::jsonb, '{"source": "curator-drafted; grounded in Chira, Kirby, Epperlein & Bräuer (2023, Scientific Reports, doi:10.1038/s41598-023-31938-5, 124-society cross-cultural dog-use data; DOI Crossref-verified 2026-09-03) and the 5-society hunting-dog field study (Vanuatu, Mongolia, Madagascar, Peru, Germany) described at eva.mpg.de/linguistic-and-cultural-evolution/research/cool/", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['human-animal relationships','cross-cultural sample','non-WEIRD']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-domain-new-caledonian-crows', 'New Caledonian crows', 'domain', 'The only bird species besides humans known to craft hooked tools, and the only phylogenetically independent species with compelling evidence of cumulative technological culture — studied in the wild and in aviaries as a comparative test case for the origins of cumulative technology, distinct from humans'' own primate lineage.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-domain-new-caledonian-crows"}'::jsonb, '{"source": "curator-drafted; grounded in the Crow Cognition Group (CrowCoG) research program described at eva.mpg.de/linguistic-and-cultural-evolution/research/cool/", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['tool use','non-human comparative species','convergent evolution']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-method-bayesian-phylogenetics', 'Bayesian phylogenetics', 'method', 'Probabilistic tree-inference methods, adapted from evolutionary biology, used to estimate language family trees and divergence dates from lexical or typological data.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-method-bayesian-phylogenetics"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['tree inference','divergence dating']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-method-comparative-linguistics', 'Comparative linguistics', 'method', 'The classical method of systematically comparing related languages to reconstruct proto-forms and establish genealogical relationships.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-method-comparative-linguistics"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['reconstruction','cognate sets']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-method-database-construction', 'Database construction', 'method', 'Building large, structured, cross-linguistic or cross-cultural datasets that make systematic comparative and statistical analysis possible.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-method-database-construction"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['data infrastructure','coding']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-method-statistical-modeling', 'Statistical modeling', 'method', 'Quantitative modeling of patterns in linguistic and cultural data, testing hypotheses about drivers of diversification and change.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-method-statistical-modeling"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['quantitative methods']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-method-network-analysis', 'Network analysis', 'method', 'Graph-based methods for representing and analyzing contact, borrowing, and influence relationships between languages or cultural traditions that don''t fit a strict tree model.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-method-network-analysis"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['graph methods','contact linguistics']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-method-text-mining', 'Text mining', 'method', 'Computational extraction of patterns and structure from large bodies of text, used to study semantic change and narrative motifs at scale.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-method-text-mining"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['computational linguistics','corpus analysis']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-method-dynamic-coevolutionary-modeling', 'Dynamic co-evolutionary modeling', 'method', 'Phylogenetic comparative models that test whether two traits (e.g. a cultural practice and a form of social organization) changed together over evolutionary time as a coupled dynamical system, distinguishing genuine co-evolution from a correlation that disappears once shared ancestry or spatial non-independence is controlled for.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-method-dynamic-coevolutionary-modeling"}'::jsonb, '{"source": "curator-drafted; grounded in Hrnčíř et al. 2025b''s use of ''recently developed dynamic co-evolutionary models'' to test kava/sociopolitical-institution co-evolution (eva.mpg.de/linguistic-and-cultural-evolution/research/cool/)", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Pagel-style models','trait co-evolution','phylogenetic comparative methods']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-method-cross-cultural-field-experiments', 'Cross-cultural field experiments', 'method', 'Standardized experimental test batteries and questionnaires administered by researchers in person across multiple, culturally and ecologically diverse field sites, allowing rigorous experimental comparison rather than reliance on ethnographic databases or observational data alone.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-method-cross-cultural-field-experiments"}'::jsonb, '{"source": "curator-drafted; grounded in the 5-society hunting-dog cognition study''s 6-experiment social-cognitive test battery plus questionnaire (eva.mpg.de/linguistic-and-cultural-evolution/research/cool/)", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['field experiments','standardized test battery','cross-cultural comparison']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-topic-language-diversification', 'Language diversification', 'topic', 'How and why languages split and diverge over time, and what social and demographic factors accelerate or slow the process.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-topic-language-diversification"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['language splitting','divergence']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-topic-contact-induced-change', 'Contact-induced change', 'topic', 'Linguistic and cultural change resulting from sustained contact between populations, including borrowing, code-switching, and structural convergence.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-topic-contact-induced-change"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['borrowing','language contact']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-topic-cultural-phylogenies', 'Cultural phylogenies', 'topic', 'Tree-like reconstructions of the history of cultural traits, and the open question of when tree models are appropriate versus when reticulate/network models are needed.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-topic-cultural-phylogenies"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cultural trees','phylogenetic comparative methods']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-topic-coevolution-of-language-and-culture', 'Co-evolution of language and culture', 'topic', 'The extent to which linguistic diversification tracks, or diverges from, broader cultural and population history.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-topic-coevolution-of-language-and-culture"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['language-culture links']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-topic-semantic-universals', 'Semantic universals', 'topic', 'Whether there are recurring, cross-linguistically stable patterns in how meanings are organized and how they shift over time.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-topic-semantic-universals"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['universals','cross-linguistic patterns']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-topic-macro-historical-hypothesis-testing', 'Testing macro-historical hypotheses', 'topic', 'Subjecting influential ''big-history'' narratives about the human past — such as Jared Diamond''s axis-of-orientation hypothesis that Eurasia''s east-west geography facilitated cultural diffusion — to quantitative testing with large comparative cultural, linguistic, ecological, and archaeological datasets, rather than treating them as settled narrative.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-topic-macro-historical-hypothesis-testing"}'::jsonb, '{"source": "curator-drafted; grounded in Chira, Gray & Botero (2024, Evolutionary Human Sciences, 6: e5, doi:10.1017/ehs.2023.34, ''Geography is not destiny: A quantitative test of Diamond''s axis of orientation hypothesis''), which found ecological barriers do inhibit cultural transmission but Eurasia is not more environmentally homogeneous than other continents — DOI added and Crossref-verified 2026-09-03", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['big-history narratives','geographic diffusion','quantitative history']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-topic-intoxicants-and-sociopolitical-complexity', 'Intoxicants and sociopolitical complexity', 'topic', 'Whether traditional intoxicants (alcohol, kava) played a causal role in the emergence and maintenance of complex societies, tested against the alternative that agricultural intensity, environmental productivity, and spatial non-independence better explain any observed association.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-topic-intoxicants-and-sociopolitical-complexity"}'::jsonb, '{"source": "curator-drafted; grounded in Hrnčíř, Chira & Gray (2025, Humanities and Social Sciences Communications, doi:10.1057/s41599-025-05503-6, ''Did alcohol facilitate the evolution of complex societies?'' — 186 societies: alcohol-political complexity association modest once agriculture/productivity controlled; DOI found and Crossref-verified 2026-09-03, correcting this node''s earlier untraced ''Hrnčíř et al. 2025a'' placeholder citation — actual venue is Humanities and Social Sciences Communications, not the same journal as the companion kava paper) and Hrnčíř, Sheehan, Claessens & Gray (2026, PNAS, doi:10.1073/pnas.2521658123, ''Kava consumption and the rise of sociopolitical complexity in Oceania'' — 83 Oceanic societies: kava-complexity correlation disappears once spatial non-independence controlled; dynamic co-evolutionary models find no evidence kava and sociopolitical institutions evolved together; published year is 2026, not 2025 as this node''s own label suggested — Crossref-verified 2026-09-03, a 2025 OSF preprint of the same title also exists, doi:10.31235/osf.io/mcbdk_v1) — eva.mpg.de/linguistic-and-cultural-evolution/research/cool/", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['alcohol','kava','political complexity','social stratification']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-topic-human-dog-relationships', 'Human-dog relationships across cultures', 'topic', 'How the dog-human bond varies and stays stable across culturally and ecologically diverse societies — both the ethnographic record of dog use, care, and treatment, and direct cross-cultural experimental comparison of dog-owner social cognition, addressing a WEIRD bias in animal cognition research that mirrors the one long noted in human psychology.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-topic-human-dog-relationships"}'::jsonb, '{"source": "curator-drafted; grounded in Chira, Kirby, Epperlein & Bräuer (2023, Scientific Reports, doi:10.1038/s41598-023-31938-5, ''Function predicts how people treat their dogs in a global sample'' — 124 societies: closer human-dog relationships linked to multifunctional roles — hunting, guarding, herding — with positive care and harsh treatment frequently co-occurring; DOI Crossref-verified 2026-09-03) and the 5-society hunting-dog cognition field study (Vanuatu, Mongolia, Madagascar, Peru, Germany: striking cross-cultural similarity in dog-human social-cognitive bonds) — eva.mpg.de/linguistic-and-cultural-evolution/research/cool/", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['dog domestication','WEIRD bias','social cognition','cross-cultural field study']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-topic-cumulative-technological-culture-in-crows', 'Cumulative technological culture in New Caledonian crows', 'topic', 'What traits enable cumulative technological culture to emerge, studied through the only phylogenetically independent non-human species with compelling evidence of it — combining field censuses of tool designs and their social/asocial learning contexts with aviary experiments on the (a)social learning mechanisms and cognitive abilities (e.g. probabilistic inference, overhypothesis formation) that support them.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-topic-cumulative-technological-culture-in-crows"}'::jsonb, '{"source": "curator-drafted; grounded in the Crow Cognition Group (CrowCoG) research program''s documented geographic diversity in tool designs, potential generational nut-dropping styles, and cognitive mechanisms — eva.mpg.de/linguistic-and-cultural-evolution/research/cool/", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cumulative culture','tool traditions','comparative cognition','convergent evolution']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-topic-religious-diversity-evolution', 'Evolution of religious diversity', 'topic', 'Phylogenetic and comparative reconstruction of how global religious diversity arose and diversified, testing specific historical hypotheses about the deep structure of that diversification rather than treating it as a single, uniform process.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-topic-religious-diversity-evolution"}'::jsonb, '{"source": "curator-drafted; grounded in Ejova, Sheehan, Bouckaert, Greenhill, Krátký, Kotherová, Cigán, Kundtová Klocová, Kundt, Watts, Bulbulia, Atkinson & Gray (2025, Evolutionary Human Sciences, 7: e43, doi:10.1017/ehs.2025.10027, ''Three evolutionary radiations shaped the evolution of global religious diversity'') — DOI added and Crossref-verified 2026-09-03", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['religion','cultural phylogenetics','diversification']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-topic-indo-european-homeland', 'Indo-European homeland debate', 'topic', 'Where and when the Indo-European language family originated and spread — the long-running contest between an Anatolian farming-expansion origin (~9,500 years ago) and a Pontic-Caspian steppe-migration origin (~6,000 years ago), tested with Bayesian linguistic phylogenetics and, more recently, reconciled against ancient-DNA migration evidence rather than settled by either dataset alone.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-topic-indo-european-homeland"}'::jsonb, '{"source": "curator-drafted; grounded in Bouckaert, Lemey, Dunn, Greenhill, Alekseyenko, Drummond, Gray, Suchard & Atkinson (2012, Science, doi:10.1126/science.1219669, ''Mapping the Origins and Expansion of the Indo-European Language Family'' — Bayesian phylogeography supporting an Anatolian origin), Haak et al. (2015, Nature, doi:10.1038/nature14317, ''Massive migration from the steppe was a source for Indo-European languages in Europe'' — ancient-DNA evidence for steppe migration), and Heggarty, Anderson, Scarborough, King, Bouckaert et al. (2023, Science, doi:10.1126/science.abg0818, ''Language trees with sampled ancestors support a hybrid model for the origin of Indo-European languages'' — 162-language IE-CoR dataset, hybrid model: homeland south of the Caucasus with a branch onto the Pontic-Caspian steppe, reconciling both hypotheses; all three DOIs Crossref-verified 2026-09-03) — the same real science already underlying this repo''s live `dlce-indoeuropean` whiteboard module, see docs/dlce-geographic-diversity-and-research-frames.md", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Indo-European','homeland hypothesis','language phylogeny','steppe migration']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-topic-gene-language-correlation', 'Genetic-linguistic population correlation', 'topic', 'Whether population-genetic structure and linguistic-family structure track the same underlying population history, and where they diverge — e.g. language shift without population replacement, or population replacement without language shift — a comparative program spanning population genetics, archaeology, and historical linguistics since its founding synthesis.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-topic-gene-language-correlation"}'::jsonb, '{"source": "curator-drafted; grounded in Cavalli-Sforza, Piazza, Menozzi & Mountain (1988, PNAS, doi:10.1073/pnas.85.16.6002, ''Reconstruction of human evolution: bringing together genetic, archaeological, and linguistic data'' — DOI added and Crossref-verified 2026-09-03), the founding paper of this comparative genetic-linguistic program, which DLCE''s own dlce-topic-coevolution-of-language-and-culture continues in updated form", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['gene-language correlation','population history','comparative synthesis']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-topic-genetic-basis-of-language-capacity', 'Genetic basis of language capacity', 'topic', 'The genetic and molecular substrate of the human capacity for speech and language, and when in human evolution it arose — most prominently studied through FOXP2, a gene whose disruption causes a severe inherited speech/language disorder and whose human-specific amino-acid changes show a molecular signature of positive selection.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-topic-genetic-basis-of-language-capacity"}'::jsonb, '{"source": "curator-drafted; grounded in Lai, Fisher, Hurst, Vargha-Khadem & Monaco (2001, Nature, doi:10.1038/35097076, FOXP2 mutation causing the KE family''s speech/language disorder), Enard, Przeworski, Fisher, Lai, Wiebe, Kitano, Monaco & Pääbo (2002, Nature, doi:10.1038/nature01025, human-specific FOXP2 substitutions bearing a signature of positive selection), and Krause, Lalueza-Fox, Orlando, Enard, Green, Burbano, Hublin, Hänni, Fortea, de la Rasilla, Bertranpetit, Rosas & Pääbo (2007, Current Biology, doi:10.1016/j.cub.2007.10.008, ''The Derived FOXP2 Variant of Modern Humans Was Shared with Neandertals'' — all three DOIs Crossref-verified 2026-09-03)", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['FOXP2','language capacity','molecular evolution','positive selection']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-scicomm-language-documentation-communities', 'Documentation of endangered and minority languages', 'scicomm-sensitivity', 'Language documentation data (recordings, transcriptions, dictionaries) is a form of community cultural heritage, not just raw research material — leading practice treats speakers as knowledge-holders and partners in what gets documented, archived, and made public, not just as data sources.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-scicomm-language-documentation-communities"}'::jsonb, '{"source": "curator-drafted; grounded in documented community-based language-documentation ethics practice (e.g. community-controlled archiving standards used in language-revitalization work)", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['language documentation','cultural heritage','informed consent','endangered languages']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('dlce-scicomm-language-death-deficit-framing', '''Language death'' deficit framing', 'scicomm-sensitivity', 'DLCE''s research on language diversification and contact-induced change documents real, often externally-driven pressures on minority languages, but the standard media vocabulary for describing this (''endangered,'' ''dying,'' ''extinct'') was itself developed in a way some linguists and communities now consider to import a biological-extinction metaphor that doesn''t fit how communities themselves experience language shift and revitalization.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "dlce-scicomm-language-death-deficit-framing"}'::jsonb, '{"source": "curator-drafted; grounded in documented critiques of biological-extinction metaphors in endangered-language discourse within linguistics", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['language endangerment','deficit framing','revitalization']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-theory-molecular-evolution', 'Molecular evolution', 'theory', 'The study of how DNA, RNA, and protein sequences change over evolutionary time, and the mechanisms (mutation, selection, drift) that drive those changes.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-theory-molecular-evolution"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['sequence evolution','mutation']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-theory-population-genetics', 'Population genetics', 'theory', 'The mathematical theory of how allele and genotype frequencies change within populations under mutation, selection, drift, and migration.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-theory-population-genetics"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['allele frequency','quantitative theory']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-theory-neutral-theory', 'Neutral theory', 'theory', 'Kimura''s theory that most molecular-level evolutionary change is driven by random drift of selectively neutral or nearly-neutral mutations, not positive selection.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-theory-neutral-theory"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Kimura','genetic drift']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-theory-selection-and-drift', 'Selection and drift', 'theory', 'The interplay between deterministic natural selection and stochastic genetic drift in shaping allele frequency trajectories, especially in small populations.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-theory-selection-and-drift"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['evolutionary forces','stochasticity']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-theory-coalescent-theory', 'Coalescent theory', 'theory', 'A retrospective model of how gene lineages sampled from a population trace back to common ancestors, foundational for inferring demographic and selective history from genomic data.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-theory-coalescent-theory"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['gene genealogies','demographic inference']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-theory-mutation-selection-balance', 'Mutation-selection balance', 'theory', 'The equilibrium reached when new deleterious mutations entering a population are balanced by selection removing them, used to explain persistence of disease alleles.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-theory-mutation-selection-balance"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['deleterious mutation','equilibrium']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-theory-evolutionary-genomics', 'Evolutionary genomics', 'theory', 'The genome-wide study of evolutionary processes, integrating population genetics theory with large-scale sequencing data.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-theory-evolutionary-genomics"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['genome-scale analysis']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-domain-modern-human-genomes', 'Modern human genomes', 'domain', 'Present-day human genomic sequence data, used as the baseline for detecting selection, admixture, and functional variation.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-domain-modern-human-genomes"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['human genomics']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-domain-archaic-hominin-genomes', 'Archaic hominin genomes', 'domain', 'Genomic sequences recovered from Neanderthals, Denisovans, and other archaic hominins, used to reconstruct their biology and legacy in modern humans.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-domain-archaic-hominin-genomes"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Neanderthal genome','Denisovan genome']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-domain-comparative-primate-genomics', 'Comparative primate genomics', 'domain', 'Cross-species comparison of primate genomes to identify human-specific and lineage-specific genomic changes.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-domain-comparative-primate-genomics"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['primate genomes','cross-species comparison']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-domain-functional-genomics', 'Functional genomics', 'domain', 'The study of gene and genome function — expression, regulation, and molecular activity — beyond sequence alone.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-domain-functional-genomics"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['gene function','genome activity']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-domain-regulatory-elements', 'Regulatory elements', 'domain', 'Non-coding genomic sequences (promoters, enhancers) that control when and where genes are expressed, an important substrate for evolutionary change.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-domain-regulatory-elements"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['gene regulation','non-coding DNA']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-domain-mitochondrial-dna', 'Mitochondrial DNA', 'domain', 'Maternally inherited genetic material used for tracing matrilineal ancestry and population history due to its high copy number and lack of recombination.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-domain-mitochondrial-dna"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['mtDNA','maternal lineage']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-domain-y-chromosome-variation', 'Y-chromosome variation', 'domain', 'Patrilineally inherited genetic variation used for tracing paternal ancestry and population history.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-domain-y-chromosome-variation"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Y-DNA','paternal lineage']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-method-whole-genome-sequencing', 'Whole-genome sequencing', 'method', 'Sequencing of an organism''s entire genome, providing comprehensive coverage for evolutionary and functional analysis.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-method-whole-genome-sequencing"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['WGS','sequencing']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-method-exome-sequencing', 'Exome sequencing', 'method', 'Targeted sequencing of only the protein-coding regions of the genome, a cost-effective way to focus on functionally interpretable variation.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-method-exome-sequencing"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['exome','coding regions']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-method-genotype-imputation', 'Genotype imputation', 'method', 'Statistical inference of unobserved genotypes using a reference panel of haplotypes, extending the value of sparser genotyping data.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-method-genotype-imputation"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['imputation','reference panels']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-method-haplotype-based-inference', 'Haplotype-based inference', 'method', 'Analysis of linked variant combinations inherited together, used to detect selection, admixture, and recent demographic events.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-method-haplotype-based-inference"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['haplotype analysis','linkage']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-method-selection-scans', 'Selection scans', 'method', 'Genome-wide statistical tests that identify regions bearing the signature of past natural selection.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-method-selection-scans"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['selection detection','genome scans']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-method-linkage-disequilibrium-analysis', 'Linkage disequilibrium analysis', 'method', 'Analysis of non-random association between alleles at different loci, informative about recombination history, selection, and population structure.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-method-linkage-disequilibrium-analysis"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['LD','recombination']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-method-phylogenomic-analysis', 'Phylogenomic analysis', 'method', 'Reconstruction of evolutionary relationships using genome-scale sequence data rather than single genes or markers.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-method-phylogenomic-analysis"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['phylogenomics','tree inference']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-method-functional-annotation', 'Functional annotation', 'method', 'Computational and experimental assignment of biological function to genomic regions and variants.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-method-functional-annotation"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['annotation','variant interpretation']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-method-expression-quantitative-trait-loci', 'Expression quantitative trait loci', 'method', 'Genomic loci (eQTLs) statistically associated with variation in gene expression levels, linking genotype to regulatory phenotype.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-method-expression-quantitative-trait-loci"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['eQTL','gene expression']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-method-crispr-archaic-allele-reversion', 'CRISPR-based archaic-allele reversion', 'method', 'Genome-editing technique that reverts modern human stem-cell DNA to the ancestral or archaic (Neanderthal/Denisovan) state at one specific site, creating ''Neandertalized'' cell lines that isolate the functional effect of a single human-specific genetic change from the rest of the genome.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-method-crispr-archaic-allele-reversion"}'::jsonb, '{"source": "curator-drafted; grounded in Stephan Riesenberg''s Genome Engineering and Repair group, eva.mpg.de/genetics/", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['CRISPR-Cas9','stem cells','genome engineering']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-topic-introgression-from-archaic-hominins', 'Introgression from archaic hominins', 'topic', 'The functional and phenotypic consequences of Neanderthal- and Denisovan-derived genetic variants persisting in modern human genomes.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-topic-introgression-from-archaic-hominins"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['archaic introgression','Neanderthal']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-topic-adaptive-evolution', 'Adaptive evolution', 'topic', 'Identifying and characterizing genomic regions that have been shaped by positive selection in human or primate lineages.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-topic-adaptive-evolution"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['positive selection','adaptation']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-topic-disease-associated-variants', 'Disease-associated variants', 'topic', 'The evolutionary origins and population-frequency dynamics of genetic variants linked to disease risk.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-topic-disease-associated-variants"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['disease genetics','risk alleles']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-topic-demographic-bottlenecks', 'Demographic bottlenecks', 'topic', 'Episodes of sharp population-size reduction inferred from genomic diversity patterns, and their long-term effects on genetic variation.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-topic-demographic-bottlenecks"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['population contraction','genetic diversity']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-topic-effective-population-size', 'Effective population size', 'topic', 'The idealized population size that would produce the observed level of genetic drift, a key parameter for interpreting diversity and selection.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-topic-effective-population-size"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Ne','population genetics parameter']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-topic-genetic-load', 'Genetic load', 'topic', 'The accumulated burden of deleterious mutations in a population or genome, and how it varies with demographic history and inbreeding.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-topic-genetic-load"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['deleterious mutations','fitness burden']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-topic-evolution-of-gene-regulation', 'Evolution of gene regulation', 'topic', 'How changes in regulatory sequence and expression, rather than protein-coding sequence, have contributed to phenotypic evolution.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-topic-evolution-of-gene-regulation"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['regulatory evolution','expression divergence']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-topic-comparative-genomics-of-primates', 'Comparative genomics of primates', 'topic', 'Identifying genomic changes unique to specific primate lineages, including humans, to understand the genetic basis of lineage-specific traits.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-topic-comparative-genomics-of-primates"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['primate comparison','lineage-specific evolution']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-topic-covid19-neanderthal-haplotypes', 'Neanderthal-introgressed COVID-19 risk and protective haplotypes', 'topic', 'Two distinct Neanderthal-derived genomic regions with opposite, clinically real effects on COVID-19 severity in living carriers: a chromosome-3 haplotype (near CXCR6/LZTFL1) substantially raising risk of severe disease, and a chromosome-12 haplotype (the OAS gene cluster) associated with reduced risk — the clearest contemporary-health case of archaic introgression''s ongoing functional relevance.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-topic-covid19-neanderthal-haplotypes"}'::jsonb, '{"source": "curator-drafted; grounded in Zeberg & Pääbo (2020, Nature 587:610-612, doi:10.1038/s41586-020-2818-3) and Zeberg & Pääbo (2021, PNAS 118(9):e2026309118, doi:10.1073/pnas.2026309118)", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Neanderthal introgression','COVID-19','CXCR6','OAS genes']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-topic-archaic-y-chromosome-mtdna-replacement', 'Archaic Y-chromosome and mtDNA replacement', 'topic', 'Both the Y chromosome and mitochondrial DNA of Neanderthals appear to have been replaced by early-modern-human-derived versions via gene flow roughly 100,000-370,000 years ago — a distinct, earlier and more complete replacement pattern than the partial autosomal admixture that left most living non-Africans with Neanderthal ancestry.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-topic-archaic-y-chromosome-mtdna-replacement"}'::jsonb, '{"source": "curator-drafted; grounded in Petr, Hajdinjak, Fu, Essel, Rougier, Crevecoeur, et al. & Kelso (2020, Science 369(6511):1653-1656, doi:10.1126/science.abb6460, ''The evolutionary history of Neanderthal and Denisovan Y chromosomes'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Y chromosome','mitochondrial DNA','archaic introgression','gene flow']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-topic-neanderthal-admixture-timing', 'Timing of the single major Neanderthal admixture pulse', 'topic', 'Genomes from ~45,000-year-old modern humans show Neanderthal ancestry segments tracing to one shared admixture event, refining when interbreeding actually happened — roughly 45,000-49,000 years ago, in a window estimated to have lasted about 7,000 years — rather than a vaguer ''sometime after leaving Africa'' estimate.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-topic-neanderthal-admixture-timing"}'::jsonb, '{"source": "curator-drafted; grounded in Sümer, Rougier, Villalba-Mouco, et al., Kelso, Zeberg, ..., Peter, Meyer, ..., Hajdinjak, Prüfer & Krause (2024, Nature, doi:10.1038/s41586-024-08420-x, ''Earliest modern human genomes constrain timing of Neanderthal admixture'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Neanderthal admixture','Ranis','modern human origins','molecular dating']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-topic-pain-sensitivity-introgression', 'Neanderthal introgression and pain sensitivity', 'topic', 'Three Neanderthal-introgressed missense variants in SCN9A, the gene encoding the pain channel Nav1.7, are associated with a lower mechanical pain threshold after sensitization in a modern human cohort — a concrete example connecting archaic introgression to a specific, testable physiological trait rather than a diffuse behavioral claim.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-topic-pain-sensitivity-introgression"}'::jsonb, '{"source": "curator-drafted; grounded in Zeberg et al., incl. Pääbo (2023, Communications Biology 6:981, doi:10.1038/s42003-023-05286-z, ''Neanderthal introgression in SCN9A impacts mechanical pain sensitivity'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['SCN9A','pain perception','archaic introgression','ion channels']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-topic-functional-validation-of-archaic-variants', 'Functional validation of archaic-derived genetic variants', 'topic', 'Testing what a specific human-specific or archaic-introgressed genetic change actually does — via CRISPR-based reversion of modern human stem cells to the ancestral/archaic state (Stephan Riesenberg''s Genome Engineering and Repair group) — and, just as importantly, critically re-examining other labs'' functional claims when the underlying cell lines or methods don''t support them.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-topic-functional-validation-of-archaic-variants"}'::jsonb, '{"source": "curator-drafted; grounded in Stephan Riesenberg''s Genome Engineering and Repair group (current EvoGen research group, eva.mpg.de/genetics/) and Maricic, Riesenberg & Pääbo (2021, Science 374:eabi6060, doi:10.1126/science.abi6060)", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['CRISPR','stem cells','functional genomics','scientific self-correction']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-scicomm-mouse-models-for-human-variants', 'Mouse models for functional validation of human-evolutionary variants', 'scicomm-sensitivity', 'This is standard, tightly regulated animal-research practice used to test what a genetic difference actually does, but ''putting a human gene variant into a mouse'' is exactly the kind of phrase that reads very differently to a lay audience than to a geneticist.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-scicomm-mouse-models-for-human-variants"}'::jsonb, '{"source": "curator-drafted; grounded in documented functional genomics practice using mouse models to test human-specific and archaic-introgressed regulatory variants", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['animal models','mouse research','functional genomics','3Rs']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-scicomm-disease-variant-population-framing', 'Disease-associated variants and population framing', 'scicomm-sensitivity', 'EvoGen''s work on disease-associated variants and genetic load is about population history and molecular mechanism, not about ranking populations, but the distinction is exactly what gets lost when a finding is compressed into a headline.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-scicomm-disease-variant-population-framing"}'::jsonb, '{"source": "curator-drafted; grounded in documented critiques of genetic-determinist and racialized misreadings of population-genetics findings", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['disease variants','population genetics','genetic determinism','race and genetics']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-scicomm-archaic-introgression-headlines', '''Percent Neanderthal'' popular narratives', 'scicomm-sensitivity', 'EvoGen studies the functional and phenotypic consequences of specific introgressed variants — most of the archaic-derived genome has no known effect at all — but public narratives tend to treat ''percent archaic ancestry'' itself as the meaningful finding.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-scicomm-archaic-introgression-headlines"}'::jsonb, '{"source": "curator-drafted; grounded in documented public-communication critiques of consumer ancestry-testing narratives around archaic introgression", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['archaic introgression','public narratives','genetic determinism']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('evogen-scicomm-genomic-sample-donor-communities', 'Genomic sampling of diverse global populations', 'scicomm-sensitivity', 'EvoGen''s population-genomics work depends on this kind of broad sampling to represent real human genetic diversity rather than over-relying on already-oversampled populations, which is itself a scientific-quality and equity issue, not just an ethics add-on.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "evogen-scicomm-genomic-sample-donor-communities"}'::jsonb, '{"source": "curator-drafted; grounded in the documented Havasupai Tribe genomic-consent case and broader calls for equitable, diverse genomic reference panels", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['genomic sampling','informed consent','data sovereignty','population diversity']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-theory-hominin-evolution', 'Hominin evolution', 'theory', 'The broad evolutionary account of the lineage leading to modern humans, spanning multiple extinct hominin species and their relationships.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-theory-hominin-evolution"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['human lineage','paleoanthropology']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-theory-life-history-evolution', 'Life history evolution', 'theory', 'How the timing of growth, maturation, and reproduction evolved across hominin lineages, inferred from skeletal and dental developmental evidence.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-theory-life-history-evolution"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['growth','maturation','development']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-theory-paleoanthropology', 'Paleoanthropology', 'theory', 'The broader discipline studying human evolution through fossil, archaeological, and comparative anatomical evidence.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-theory-paleoanthropology"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['fossil record','human evolution']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-theory-evolutionary-morphology', 'Evolutionary morphology', 'theory', 'The study of how anatomical form has changed over evolutionary time in response to functional and developmental constraints.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-theory-evolutionary-morphology"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['anatomy','form and function']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-theory-adaptation', 'Adaptation', 'theory', 'The theory that anatomical and behavioral traits evolve in response to selective pressures from the environment and way of life.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-theory-adaptation", "conceptBaseId": "OE-CONCEPT-bio-core-adaptation"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['natural selection','functional traits']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-theory-biomechanics', 'Biomechanics', 'theory', 'The application of mechanical principles to understand how skeletal form relates to movement and function, e.g. in reconstructing locomotion from fossil bones.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-theory-biomechanics"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['locomotion','mechanical function']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-domain-fossil-hominins', 'Fossil hominins', 'domain', 'Skeletal and dental remains of extinct members of the human lineage, the primary physical evidence for reconstructing human evolutionary history.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-domain-fossil-hominins", "conceptBaseId": "OE-SANDBOX-CONCEPT-000001"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['hominin fossils','paleontology']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-domain-paleoenvironments', 'Paleoenvironments', 'domain', 'Reconstructions of past climates, landscapes, and ecosystems that hominins inhabited, used to contextualize evolutionary and behavioral change.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-domain-paleoenvironments"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['past climate','landscape reconstruction']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-domain-stone-tools', 'Stone tools', 'domain', 'Lithic artifacts produced by hominins, used as evidence for cognitive, behavioral, and technological evolution.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-domain-stone-tools", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-technology"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['lithics','technology']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-domain-skeletal-morphology', 'Skeletal morphology', 'domain', 'The form and structure of bones, analyzed comparatively across hominin species to reconstruct locomotion, body size, and life history.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-domain-skeletal-morphology"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['bone morphology','comparative anatomy']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-domain-dental-evolution', 'Dental evolution', 'domain', 'Changes in tooth form, wear, and development across hominin lineages, informative about diet, growth rate, and taxonomy.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-domain-dental-evolution"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['teeth','diet reconstruction']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-domain-paleogenomics', 'Paleogenomics', 'domain', 'Ancient genomic evidence integrated with fossil and archaeological data to address questions about hominin origins and relationships.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-domain-paleogenomics"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['ancient DNA','genomics']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-method-geometric-morphometrics', 'Geometric morphometrics', 'method', 'Quantitative analysis of shape using coordinates of anatomical landmarks, allowing statistical comparison of skeletal form across specimens and species.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-method-geometric-morphometrics"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['shape analysis','landmarks']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-method-ct-scanning', 'CT scanning', 'method', 'Computed tomography imaging used to non-destructively visualize internal bone and dental structure in fossil specimens.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-method-ct-scanning"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['imaging','internal structure']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-method-3d-reconstruction', '3D reconstruction', 'method', 'Digital modeling of fragmentary or distorted fossil remains into complete three-dimensional forms for analysis.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-method-3d-reconstruction"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['digital modeling','virtual reconstruction']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-method-stable-isotopes', 'Stable isotopes', 'method', 'Chemical analysis of isotope ratios in bones and teeth used to reconstruct diet, mobility, and environment.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-method-stable-isotopes"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['isotope analysis','diet reconstruction']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-method-paleoecology', 'Paleoecology', 'method', 'Reconstruction of past ecological relationships and habitats from fossil and sedimentary evidence.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-method-paleoecology"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['past ecosystems','habitat reconstruction']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-method-taphonomy', 'Taphonomy', 'method', 'The study of what happens to organic remains between death and fossilization/discovery, essential for correctly interpreting the fossil record.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-method-taphonomy"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['fossilization processes','site formation']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-method-radiocarbon-dating', 'Radiocarbon dating', 'method', 'Radiometric dating of organic material based on carbon-14 decay, used to establish chronologies for sites within its ~50,000-year range.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-method-radiocarbon-dating"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['dating methods','chronology']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-method-proteomics', 'Proteomics', 'method', 'Analysis of ancient proteins preserved in fossils, useful for taxonomic identification and phylogenetic placement when DNA is not preserved.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-method-proteomics"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['ancient proteins','molecular taxonomy']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-method-trabecular-bone-analysis', 'Trabecular and cortical bone microstructure analysis', 'method', 'MicroCT-based quantification of a bone''s internal architecture — the density and orientation of spongy trabecular bone, and the thickness of dense cortical bone — used as a functional signal of how a limb or digit was actually loaded and used during life, distinct from and complementary to external shape (geometric morphometrics).', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-method-trabecular-bone-analysis"}'::jsonb, '{"source": "curator-drafted; grounded in Tracy Kivell''s research program (eva.mpg.de/human-origins/staff/tracy-kivell/) and Bird, Kivell, Dunmore & Skinner (2023, American Journal of Biological Anthropology, doi:10.1002/ajpa.24824)", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['microCT','internal bone structure','biomechanics']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-method-controlled-experimental-replication', 'Controlled experimental replication', 'method', 'Actualistic experiments that reproduce a candidate archaeological signature under controlled, known conditions — e.g. trampling flint flakes on measured substrates to see what edge damage results — so that a real archaeological pattern can be tested against a known-cause baseline rather than interpreted on typological grounds alone.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-method-controlled-experimental-replication"}'::jsonb, '{"source": "curator-drafted; grounded in McPherron, Braun, Dogandžić, Archer, Desta & Lin (2014, Journal of Archaeological Science 49:70-82, doi:10.1016/j.jas.2014.04.003) — DOI verified live via literaturebase_verify_doi", "status": "draft", "created": "2026-09-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['experimental archaeology','actualistic studies','replication','lithic experiments']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-topic-bipedalism', 'Bipedalism', 'topic', 'The evolutionary origins and biomechanical consequences of habitual upright, two-legged locomotion, a defining hominin trait.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-topic-bipedalism"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['upright walking','locomotion']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-topic-diet-reconstruction', 'Diet reconstruction', 'topic', 'Inferring what extinct hominins ate from dental wear, isotopes, and associated archaeological evidence.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-topic-diet-reconstruction"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['paleodiet','dental evidence']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-topic-growth-and-development', 'Growth and development', 'topic', 'How the pace and pattern of skeletal and dental maturation evolved across hominin species, and what it implies about life history.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-topic-growth-and-development"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['ontogeny','maturation rate']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-topic-climate-adaptation', 'Climate adaptation', 'topic', 'How hominin anatomy and behavior adapted to changing and variable Pleistocene climates.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-topic-climate-adaptation"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['environmental adaptation','Pleistocene']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-topic-migration', 'Migration', 'topic', 'The dispersal of hominin species out of and across continents, reconstructed from fossil and archaeological distributions.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-topic-migration"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['dispersal','range expansion']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-topic-archaic-humans', 'Archaic humans', 'topic', 'The biology, behavior, and relationships of non-modern Homo populations such as Neanderthals, Denisovans, and Homo erectus.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-topic-archaic-humans"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Neanderthals','Homo erectus']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-topic-manual-dexterity-evolution', 'Evolution of manual dexterity and grip', 'topic', 'How hominin hand and thumb capability for precise manipulation evolved, assessed through internal bone structure (which tracks how a bone was actually loaded in life) rather than tool assemblages alone — current evidence shows dexterity evolved gradually and unevenly rather than as a single clean transition: Australopithecus sediba''s thumb and pinky already show human-like manipulation loading while its other fingers remain ape-like and climbing-adapted.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-topic-manual-dexterity-evolution"}'::jsonb, '{"source": "curator-drafted; grounded in Syeda, Kivell et al. (2025, Science Advances 11, doi:10.1126/sciadv.adt1201, ''Phalangeal cortical bone distribution reveals different dexterous and climbing behaviors in Australopithecus sediba and Homo naledi'') and Dunmore, Kivell, Skinner et al. (2024, American Journal of Biological Anthropology, doi:10.1002/ajpa.24695)", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['hand evolution','grip','tool use','trabecular bone']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-topic-sahelanthropus-bipedalism-debate', 'The Sahelanthropus bipedalism debate', 'topic', 'An open, actively contested question of whether Sahelanthropus tchadensis (c. 7 million years old, among the oldest putative hominins) walked habitually upright — a 2022 study argued yes from external femur/postcrania morphology, while a 2024 re-analysis incorporating internal (trabecular) bone structure found no consistent evidence for habitual bipedalism, illustrating how contested even foundational claims about hominin origins remain and how internal bone evidence can adjudicate between competing readings of the same fossils.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-topic-sahelanthropus-bipedalism-debate"}'::jsonb, '{"source": "curator-drafted; grounded in Cazenave, Pina, Hammond, et al. & Wood (2024, Journal of Human Evolution, doi:10.1016/j.jhevol.2024.103557, ''Postcranial evidence does not support habitual bipedalism in Sahelanthropus tchadensis: A reply to Daver et al. 2022'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Sahelanthropus','bipedalism','scientific debate','earliest hominins']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-topic-taphonomy-vs-intentional-modification', 'Taphonomy vs. intentional modification', 'topic', 'Distinguishing genuine hominin-made cut marks, percussion marks, and tool retouch from damage produced by natural post-depositional processes — trampling, sediment compaction, carnivore gnawing — that can closely mimic intentional modification. A methodological problem with direct stakes for how far back stone-tool use and butchery can be confidently claimed.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-topic-taphonomy-vs-intentional-modification"}'::jsonb, '{"source": "curator-drafted; grounded in McPherron, Alemseged, Marean, Wynn, Reed, Geraads, Bobe & Béarat (2010, Nature, doi:10.1038/nature09248, ''Evidence for stone-tool-assisted consumption of animal tissues before 3.39 million years ago at Dikika, Ethiopia'') and McPherron, Braun, Dogandžić, Archer, Desta & Lin (2014, Journal of Archaeological Science 49:70-82, doi:10.1016/j.jas.2014.04.003, controlled trampling/edge-damage replication experiments) — both DOIs verified live via literaturebase_verify_doi", "status": "draft", "created": "2026-09-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['taphonomy','trampling','experimental archaeology','pseudo-retouch','edge damage']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-scicomm-fossil-collections-and-colonial-history', 'Fossil hominin collections with colonial-era acquisition histories', 'scicomm-sensitivity', 'Contemporary practice increasingly requires genuine host-country partnership (co-authorship, capacity building, specimens remaining in or returning to the country of origin) rather than the older extractive model where fossils traveled to European or North American institutions and host-country researchers did not.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-scicomm-fossil-collections-and-colonial-history"}'::jsonb, '{"source": "curator-drafted; grounded in documented critiques of colonial-era paleoanthropological collecting practice and calls for host-country research partnership", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['fossil hominins','colonial history','repatriation','research partnership']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('humor-scicomm-linear-progress-narratives', '''Missing link'' and linear-progress narratives', 'scicomm-sensitivity', 'HumOr''s own research on hominin diversity, archaic humans, and coexisting lineages directly contradicts the linear-progress image, but that image is so culturally entrenched that it resurfaces by default unless exhibit and press copy actively work against it.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "humor-scicomm-linear-progress-narratives"}'::jsonb, '{"source": "curator-drafted; grounded in well-documented critiques of the ''March of Progress'' image and linear human-evolution narratives in science communication and museum studies", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['human evolution narratives','March of Progress','exhibit design','public misconceptions']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-theory-primate-social-evolution', 'Primate social evolution', 'theory', 'The study of how social organization, group living, and social bonds evolved across primate species in response to ecological and reproductive pressures.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-theory-primate-social-evolution"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['sociality','group living']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-theory-life-history-theory', 'Life history theory', 'theory', 'An evolutionary framework explaining how primates allocate resources between growth, reproduction, and survival across the lifespan.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-theory-life-history-theory"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['growth','reproduction','trade-offs']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-theory-behavioral-ecology', 'Behavioral ecology', 'theory', 'The study of how primate behavior is shaped by ecological conditions such as food distribution, predation risk, and habitat structure to maximize fitness.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-theory-behavioral-ecology"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['ecology','adaptive behavior']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-theory-social-network-theory', 'Social network theory', 'theory', 'A framework for representing and analyzing the structure of social relationships within a group as a network of connections, used to study bonds, hierarchy, and information flow.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-theory-social-network-theory"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['network structure','social relationships']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-theory-cooperation-and-conflict', 'Cooperation and conflict', 'theory', 'Theoretical frameworks explaining when primates cooperate versus compete, including coalition formation and conflict resolution.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-theory-cooperation-and-conflict"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['coalitions','conflict resolution']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-theory-sexual-selection', 'Sexual selection', 'theory', 'The theory that traits can evolve because they increase mating success rather than survival, shaping primate mating systems, ornamentation, and competition.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-theory-sexual-selection"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['mate choice','intrasexual competition']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-theory-parental-investment', 'Parental investment', 'theory', 'Trivers'' theory that the sex investing more in offspring becomes the choosier sex, shaping mating systems and parental care patterns across primates.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-theory-parental-investment"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Trivers','parental care']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-domain-wild-primate-populations', 'Wild primate populations', 'domain', 'Free-ranging, non-captive primate groups studied in their natural habitats, providing ecologically valid behavioral data.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-domain-wild-primate-populations"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['field populations','wild behavior']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-domain-baboons', 'Baboons', 'domain', 'Old World monkeys widely studied as a model for understanding primate social structure, stress physiology, and life history under variable ecological conditions.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-domain-baboons"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Papio','Old World monkeys']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-domain-chimpanzees', 'Chimpanzees', 'domain', 'Humans'' closest living relatives, extensively studied for insight into the evolutionary origins of cooperation, culture, and cognition.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-domain-chimpanzees"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Pan troglodytes','great apes']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-domain-monkeys', 'Monkeys', 'domain', 'Old and New World monkey species studied comparatively across the primate order for insight into the diversity of social and reproductive strategies.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-domain-monkeys"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['primates','comparative study']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-domain-social-groups', 'Social groups', 'domain', 'The composition, size, and organization of primate social units, studied for their ecological and evolutionary drivers.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-domain-social-groups"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['group composition','social organization']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-domain-dominance-hierarchies', 'Dominance hierarchies', 'domain', 'Rank-ordered systems of social status within primate groups that shape access to resources, mates, and social support.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-domain-dominance-hierarchies"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['rank','social status']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-domain-mating-systems', 'Mating systems', 'domain', 'The patterns of sexual pairing (monogamy, polygyny, promiscuity) observed across primate species and their ecological correlates.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-domain-mating-systems"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['mating strategies','reproductive systems']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-domain-dispersal', 'Dispersal', 'domain', 'The movement of individuals away from their natal group, a key process shaping gene flow, social structure, and inbreeding avoidance.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-domain-dispersal"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['natal dispersal','gene flow']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-domain-kinship', 'Kinship', 'domain', 'Genetic relatedness among group members and its influence on cooperative and competitive social behavior.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-domain-kinship"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['relatedness','kin bonds']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-domain-gorillas', 'Gorillas', 'domain', 'Wild gorilla populations, studied for social organization, sociality, and — via the department''s Social Microbiome group — gut microbiome variation shaped by social group membership and host ecology rather than diet or phylogeny alone.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-domain-gorillas"}'::jsonb, '{"source": "curator-drafted; grounded in Martha Robbins'' Gorilla Group, a current PrimEvo research group (eva.mpg.de/primate-behavior-and-evolution/)", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Gorilla','great apes','sociality']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-domain-pan-african-chimpanzee-populations', 'Pan-African chimpanzee populations', 'domain', 'Chimpanzee populations sampled across all four Pan troglodytes subspecies at over 40 field sites in roughly 15 African countries — a deliberately cross-sectional, breadth-over-depth research design (the Pan African Programme: The Cultured Chimpanzee, PanAf) that complements this department''s deep single-site studies (Taï, Amboseli) by comparing many populations'' ecology and behavior simultaneously rather than following one population for decades.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-domain-pan-african-chimpanzee-populations"}'::jsonb, '{"source": "curator-drafted; grounded in Kalan, Kulik, Arandjelovic, Boesch, Haas, Dieguez et al. & Kühl (2020, Nature Communications, doi:10.1038/s41467-020-18176-3) and panafrican.eva.mpg.de''s own stated ~35-40-population, cross-sectional design", "status": "draft", "created": "2026-09-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['PanAf','cross-sectional sampling','multi-site comparison','Pan troglodytes']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-method-long-term-field-observation', 'Long-term field observation', 'method', 'Multi-year, often multi-decade, systematic observation of habituated wild primate groups, enabling life-history and longitudinal social analysis.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-method-long-term-field-observation"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['longitudinal study','habituation']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-method-behavioral-sampling', 'Behavioral sampling', 'method', 'Standardized protocols (e.g. focal-animal, scan sampling) for systematically recording behavior to enable quantitative comparison.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-method-behavioral-sampling"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['focal sampling','ethogram']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-method-social-network-analysis', 'Social network analysis', 'method', 'Quantitative analysis of patterns of social interaction as network graphs, used to study bond structure, centrality, and information flow.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-method-social-network-analysis"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['network methods','graph analysis']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-method-endocrinology-and-hormones', 'Endocrinology and hormones', 'method', 'Measurement of hormone levels (e.g. cortisol, testosterone) from non-invasive samples to study stress, reproduction, and social status.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-method-endocrinology-and-hormones"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['hormone assays','physiology']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-method-genetic-relatedness-analysis', 'Genetic relatedness analysis', 'method', 'Molecular methods for determining kinship among group members, used to test how relatedness shapes cooperation and social preference.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-method-genetic-relatedness-analysis"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['kinship analysis','molecular methods']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-method-gps-tracking', 'GPS tracking', 'method', 'Satellite-based tracking of individual or group movement, used to study ranging patterns, habitat use, and dispersal.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-method-gps-tracking"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['movement data','ranging']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-method-remote-sensing-of-habitats', 'Remote sensing of habitats', 'method', 'Satellite and aerial imagery used to characterize vegetation, resource availability, and habitat change relevant to primate ecology.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-method-remote-sensing-of-habitats"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['satellite imagery','habitat mapping']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-method-health-and-parasite-monitoring', 'Health and parasite monitoring', 'method', 'Systematic assessment of disease, injury, and parasite load in wild primates, linked to social behavior, stress, and life-history outcomes.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-method-health-and-parasite-monitoring"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['disease ecology','parasitology']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-method-camera-trap-citizen-science', 'Camera-trap video with citizen-science annotation', 'method', 'Remote, unmanned camera traps deployed across many chimpanzee field sites simultaneously, generating thousands of hours of video too large for any one research team to review — annotated instead by public volunteers through the Chimp&See online citizen-science platform (identifying individuals, behaviors, and tool use), enabling behavioral comparison across dozens of populations at once rather than one deeply-studied site at a time.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-method-camera-trap-citizen-science"}'::jsonb, '{"source": "curator-drafted; grounded in Arandjelovic, Stephens, McCarthy, Dieguez, Kalan, Maldonado, Boesch & Kuehl (2016, PeerJ Preprints, doi:10.7287/peerj.preprints.1792v1, ''Chimp&See: an online citizen science platform for large-scale, remote video camera trap annotation of chimpanzee behaviour, demography and individual identification'') and McCarthy, Stephens, Dieguez, Samuni, Després-Einspenner, et al., Wittig, Boesch, Kühl & Arandjelovic (2021, Ecology and Evolution, doi:10.1002/ece3.7128, applying the platform to real individual-identification and social-network data); DOIs Crossref-verified 2026-09-04", "status": "draft", "created": "2026-09-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['camera traps','citizen science','Chimp&See','crowdsourced annotation']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-method-primate-archaeology-excavation', 'Primate archaeology (excavation of living tool-use sites)', 'method', 'Standard archaeological excavation and lithic-analysis techniques (systematic recovery, use-wear and flake-scar analysis) applied to the stone-tool-use sites of living, observable wild primates rather than only to the fossil archaeological record, allowing a directly known toolmaker and known behavior to be compared against the resulting artifact assemblage.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-method-primate-archaeology-excavation"}'::jsonb, '{"source": "curator-drafted; grounded in Proffitt, Luncz, Falótico, Ottoni, de la Torre & Haslam (2016, Nature, doi:10.1038/nature20112) and Luncz, Gill, Proffitt, Svensson, Kulik & Malaivijitnond (2019, eLife, doi:10.7554/eLife.46961) — both DOIs verified live via literaturebase_verify_doi", "status": "draft", "created": "2026-09-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['primate archaeology','lithic analysis','excavation','actualistic study']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-topic-social-bonds-and-fitness', 'Social bonds and fitness', 'topic', 'Evidence that strong, stable social relationships causally improve survival and reproductive success in primates.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-topic-social-bonds-and-fitness"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['social bonding','reproductive success']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-topic-cooperation-and-alliances', 'Cooperation and alliances', 'topic', 'How and why primates form coalitions and cooperative alliances, and what maintains them over time.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-topic-cooperation-and-alliances"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['coalitions','cooperative behavior']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-topic-reproductive-strategies', 'Reproductive strategies', 'topic', 'The diversity of strategies primates use to maximize reproductive success given their mating system, rank, and ecology.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-topic-reproductive-strategies"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['reproduction','mating strategies']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-topic-stress-and-health', 'Stress and health', 'topic', 'How social and ecological stressors affect physiological stress markers and health outcomes in wild primates.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-topic-stress-and-health"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['physiological stress','wellbeing']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-topic-early-life-adversity', 'Early life adversity', 'topic', 'The long-term consequences of adverse early-life experiences (maternal loss, low rank, drought) on adult social behavior and fitness.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-topic-early-life-adversity"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['developmental origins','maternal effects']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-topic-gene-environment-interactions', 'Gene–environment interactions', 'topic', 'How genetic variation and environmental/social conditions jointly shape primate behavior and life-history outcomes.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-topic-gene-environment-interactions"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['GxE','behavioral genetics']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-topic-social-structure-and-demography', 'Social structure and demography', 'topic', 'How group size, sex ratio, and age structure interact with social organization over time.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-topic-social-structure-and-demography"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['demography','group structure']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-topic-cultural-traditions-in-primates', 'Cultural traditions in primates', 'topic', 'Socially learned, group-specific behavioral traditions (e.g. tool use variants) documented in wild primate populations, relevant to debates about the evolutionary origins of culture.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-topic-cultural-traditions-in-primates"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['primate culture','social learning']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-topic-biological-embedding-of-early-life-adversity', 'Biological embedding of early-life adversity', 'topic', 'How environmental and social hardship in infancy leaves lasting molecular signatures — measured here as DNA-methylation patterns at hundreds of thousands of genomic sites — shaping adult health and lifespan. In wild Amboseli baboons, resource-limitation exposures (poor habitat quality, early-life drought) left far stronger, more compounding methylation signatures than social adversity (maternal loss, low rank, social isolation), challenging assumptions that social stress is the dominant embedding pathway.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-topic-biological-embedding-of-early-life-adversity"}'::jsonb, '{"source": "curator-drafted; grounded in Anderson, Lin, Lea, Johnston, Voyles, Akinyi, Archie, Alberts & Tung (2024, PNAS 121(11), doi:10.1073/pnas.2309469121, ''DNA methylation signatures of early-life adversity are exposure-dependent in wild baboons'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['DNA methylation','developmental origins','epigenetics','Amboseli']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-topic-inbreeding-avoidance', 'Inbreeding avoidance mechanisms', 'topic', 'How group-living primates avoid mating with close genetic relatives despite proximity — in wild chimpanzees, genetic relatedness estimates from exome-capture sequencing show females actively avoid close kin as mates even where both sexes sometimes remain in their natal community (bisexual philopatry), including detection of a rare, cryptic inbreeding event.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-topic-inbreeding-avoidance"}'::jsonb, '{"source": "curator-drafted; grounded in White, Städele, Ramirez Amaya, Langergraber & Vigilant (2024, Royal Society Open Science 11(1):230967, doi:10.1098/rsos.230967, ''Female chimpanzees avoid inbreeding even in the presence of substantial bisexual philopatry'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['inbreeding avoidance','kin recognition','philopatry','chimpanzees']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-topic-attachment-in-primates', 'Attachment styles in wild primates', 'topic', 'The first systematic test of human-derived attachment-style classification (organized/secure vs. insecure, disorganized) in a wild great ape — 50 Taï chimpanzee offspring aged 0-10, followed for nearly 3,800 observation hours, showed organized attachment patterns resembling human infants but no behavioral evidence of disorganized attachment, informing comparative theory on the evolutionary origins of human-specific caregiving vulnerabilities.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-topic-attachment-in-primates"}'::jsonb, '{"source": "curator-drafted; grounded in Rolland, Nodé-Langlois, Tkaczynski, Girard-Buttoz, Rayson, Crockford & Wittig (2025, Nature Human Behaviour 9:1571-1582, doi:10.1038/s41562-025-02176-8, ''Evidence of organized but not disorganized attachment in wild Western chimpanzee offspring'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['attachment theory','mother-infant bond','chimpanzees','comparative development']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-topic-social-play-and-cooperation', 'Adult social play as cooperation scaffolding', 'topic', 'Among adult (not just juvenile) wild chimpanzees, social play preceding a collective action — cooperative hunting, border patrols — increased the subsequent success of that cooperation, suggesting play functions to calibrate coordination and trust among adult cooperative partners, not just as a developmental practice arena for the young.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-topic-social-play-and-cooperation"}'::jsonb, '{"source": "curator-drafted; grounded in Samuni, Mielke, Crockford & Wittig (2024, Current Biology, doi:10.1016/j.cub.2024.10.058, ''Social play fosters cooperation in wild adult chimpanzees'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['social play','cooperation','coordination','chimpanzees']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-topic-chimpanzee-cultural-diversity', 'Pan-African chimpanzee cultural and behavioral diversity', 'topic', 'Comparing 144 behaviors across 46 chimpanzee communities found substantially more cultural diversity than any single-site study could reveal, and that environmental variability itself — not just genetic distance between populations — predicts how behaviorally diverse a community''s repertoire is, complicating any simple story of culture spreading outward from one origin point.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-topic-chimpanzee-cultural-diversity"}'::jsonb, '{"source": "curator-drafted; grounded in Kalan, Kulik, Arandjelovic, Boesch, Haas, Dieguez et al. & Kühl (2020, Nature Communications, doi:10.1038/s41467-020-18176-3, ''Environmental variability supports chimpanzee behavioural diversity'') and Boesch, Kalan, Mundry, Arandjelovic, Pika, Dieguez et al. & Kühl (2020, Nature Human Behaviour, doi:10.1038/s41562-020-0890-1, ''Chimpanzee ethnography reveals unexpected cultural diversity''); both DOIs Crossref-verified 2026-09-04", "status": "draft", "created": "2026-09-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cultural diversity','chimpanzee ethnography','environmental variability','PanAf']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-topic-accumulative-stone-throwing', 'Accumulative stone throwing and tree-directed behavior', 'topic', 'A previously undocumented, ritualized-looking chimpanzee behavior — repeatedly throwing or banging stones against the same trees, building up piles of stones and creating characteristic bark damage — recorded via camera trap at multiple West African sites, resembling human cairn-building enough to raise open questions about whether it reflects a form of symbolic or ritual-like behavior, though the function remains genuinely unresolved rather than settled.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-topic-accumulative-stone-throwing"}'::jsonb, '{"source": "curator-drafted; grounded in Kühl, Kalan, Arandjelovic, Aubert, D''Auvergne, Goedmakers et al. & Boesch (2016, Scientific Reports, doi:10.1038/srep22219, ''Chimpanzee accumulative stone throwing''); DOI Crossref-verified 2026-09-04", "status": "draft", "created": "2026-09-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['stone throwing','tool-adjacent behavior','possible ritual behavior','camera trap discovery']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-topic-primate-archaeology', 'Primate archaeology and accidental tool manufacture', 'topic', 'Applying archaeological excavation and lithic-analysis methods directly to living, observable primate tool-use sites, rather than only to the fossil/lithic record — wild bearded capuchin monkeys in Brazil, striking stones to lick mineral residue, unintentionally produce sharp stone flakes indistinguishable from classic early-hominin (Oldowan-type) tools, with no evidence the capuchins use the flakes for cutting; wild long-tailed macaques in Thailand develop distinct, group-specific tool-use ''archaeological signatures'' even where ecology is shared, showing environment alone cannot explain the pattern.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-topic-primate-archaeology"}'::jsonb, '{"source": "curator-drafted; grounded in Proffitt, Luncz, Falótico, Ottoni, de la Torre & Haslam (2016, Nature, doi:10.1038/nature20112, ''Wild monkeys flake stone tools'') and Luncz, Gill, Proffitt, Svensson, Kulik & Malaivijitnond (2019, eLife, doi:10.7554/eLife.46961, ''Group-specific archaeological signatures of stone tool use in wild macaques'') — both DOIs verified live via literaturebase_verify_doi", "status": "draft", "created": "2026-09-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['primate archaeology','stone flaking','capuchin monkeys','macaques','accidental tool production']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-scicomm-field-sites-in-range-countries', 'Long-term field sites in primate range countries', 'scicomm-sensitivity', 'PrimEvo''s core method — decades-long individual-based field observation — depends on sustained local partnership: field assistants, trackers, and community relationships that make the data possible, and that are easy to erase from how the resulting science gets told.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-scicomm-field-sites-in-range-countries"}'::jsonb, '{"source": "curator-drafted; grounded in documented critiques of parachute/extractive field science and calls for equitable field-research partnership", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['field sites','range countries','conservation','research partnership']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-scicomm-captive-primate-cognition', 'Captive primate cognition and behavior research', 'scicomm-sensitivity', 'The department''s public identity is built on wild-population fieldwork, so any captive-facility component needs its own explicit, non-evasive framing rather than being folded silently into ''primate research'' generally.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-scicomm-captive-primate-cognition"}'::jsonb, '{"source": "curator-drafted; grounded in documented zoo-based primate research practice at MPI-EVA-affiliated facilities", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['captive research','animal welfare','zoo partnership']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('primevo-scicomm-genetic-relatedness-sampling', 'Genetic sampling and hormone/health monitoring of wild populations', 'scicomm-sensitivity', 'The department''s methods are designed around minimizing disturbance to wild populations, but a lay reader encountering ''genetic sampling'' or ''hormone monitoring'' without that context may assume capture, sedation, or other invasive procedures.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "primevo-scicomm-genetic-relatedness-sampling"}'::jsonb, '{"source": "curator-drafted; grounded in standard non-invasive sampling practice in behavioral ecology and primatology", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['non-invasive sampling','animal welfare','field methods']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-theory-developmental-psychology', 'Developmental psychology', 'theory', 'The study of how cognition, social understanding, and behavior change across childhood, providing the age-graded framework CCP tests cross-culturally.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-theory-developmental-psychology", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-development"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['child development','ontogeny']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-theory-cultural-psychology', 'Cultural psychology', 'theory', 'The theory that mind and culture mutually constitute each other, motivating comparison of psychological processes across societies rather than assuming universality.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-theory-cultural-psychology", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-culture"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cross-cultural cognition','mutual constitution']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-theory-social-cognition', 'Social cognition', 'theory', 'The study of mental processes underlying how individuals perceive, interpret, and respond to social information about others.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-theory-social-cognition"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['social perception','mentalizing']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-theory-theory-of-mind', 'Theory of mind', 'theory', 'The capacity to attribute mental states — beliefs, desires, intentions — to oneself and others, and to understand that these can differ from one''s own or from reality. Central subject of the metarepresentation knowledge graph now hosted in ccp_module.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-theory-theory-of-mind", "conceptBaseId": "OE-SANDBOX-CONCEPT-000010"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['mental state attribution','metarepresentation']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-theory-learning-biases', 'Learning biases', 'theory', 'Systematic predispositions in how children selectively attend to and learn from social information, e.g. preferring prestigious, familiar, or majority models.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-theory-learning-biases"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['selective learning','cognitive biases']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-theory-individual-differences-approach', 'Individual-differences approach to cross-cultural cognition', 'theory', 'A stated methodological pivot in CCP''s own current research program: supplementing group-level cross-cultural comparison (society A vs. society B) with individual-level analysis, to identify which specific cultural and ecological factors actually drive cognitive-developmental variation, rather than treating ''culture'' as a single undifferentiated between-group variable.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-theory-individual-differences-approach"}'::jsonb, '{"source": "curator-drafted; grounded in Bohn, Fong, Pope-Caldwell, Stengelin & Haun (2024, Nature Reviews Psychology 3(10):641-643, doi:10.1038/s44159-024-00351-8, ''Understanding cultural variation in cognition one child at a time'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['methodology','individual differences','cross-cultural comparison']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-domain-children', 'Children', 'domain', 'Child participants across age ranges, the core study population for tracing the developmental emergence of social-cognitive capacities.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-domain-children"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['child participants','developmental sample']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-domain-cross-cultural-samples', 'Cross-cultural samples', 'domain', 'Study populations drawn from multiple societies, used to test whether developmental patterns found in one culture (often WEIRD samples) generalize.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-domain-cross-cultural-samples"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cross-cultural sampling','WEIRD bias']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-domain-parenting', 'Parenting', 'domain', 'Caregiving practices and their cross-cultural variation, studied as a key input shaping children''s social and cognitive development.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-domain-parenting"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['caregiving','family environment']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-domain-social-norms', 'Social norms', 'domain', 'Shared behavioral expectations within a community, studied for how and when children come to understand and enforce them.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-domain-social-norms"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['norm understanding','normativity']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-domain-moral-development', 'Moral development', 'domain', 'The emergence of moral judgment, fairness concerns, and prosocial behavior across childhood and across cultures.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-domain-moral-development"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['morality','prosocial development']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-domain-communication', 'Communication', 'domain', 'The development of communicative and language abilities, studied as both a cognitive capacity and a social tool for coordinating with others.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-domain-communication", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-communication"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['language development','communicative intent']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-domain-global-child-study-network', 'Global Child Study Network', 'domain', 'CCP''s federated network of child-testing field stations spanning Congo, Cameroon, Malaysia, Namibia, Rossel Island (Papua New Guinea), and Uganda, complementing the Leipzig-based Child Study Centre — a far broader cross-cultural footprint than the single historical Namibia site this graph previously represented CCP''s fieldwork with.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-domain-global-child-study-network"}'::jsonb, '{"source": "curator-drafted; grounded in CCP''s own stated field infrastructure, eva.mpg.de/comparative-cultural-psychology/", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['field network','cross-cultural infrastructure','child development']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-domain-great-ape-comparative-sample', 'Great ape comparative sample', 'domain', 'Captive chimpanzees, bonobos, gorillas, and orangutans tested alongside human children on matched cognitive tasks — the comparative side of CCP''s cross-species work, run through the Wolfgang Köhler Primate Research Center and led by Christoph Völter''s Pan Cultures group, which studies which ''building blocks'' of culture are shared across the four great-ape genera versus elaborated uniquely in humans.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-domain-great-ape-comparative-sample"}'::jsonb, '{"source": "curator-drafted; grounded in Christoph Völter''s Pan Cultures group (current CCP research group, eva.mpg.de/comparative-cultural-psychology/) and Kaminski, Stengelin, Girndt, Haun & Liebal (2024, PLOS ONE 19(1):e0295221, doi:10.1371/journal.pone.0295221)", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['great apes','comparative cognition','Pan Cultures']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-method-behavioral-experiments', 'Behavioral experiments', 'method', 'Controlled tasks presented to children (or comparative non-human samples) that isolate specific cognitive or social capacities.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-method-behavioral-experiments"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['experimental design','controlled tasks']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-method-eye-tracking', 'Eye-tracking', 'method', 'Recording gaze patterns to infer attention, expectation, and understanding in infants and children who cannot yet give verbal responses.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-method-eye-tracking"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['gaze data','looking-time paradigm']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-method-cross-cultural-surveys', 'Cross-cultural surveys', 'method', 'Structured questionnaires administered across societies to compare beliefs, values, and reported practices.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-method-cross-cultural-surveys"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['survey methodology','questionnaires']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-method-developmental-tasks', 'Developmental tasks', 'method', 'Age-calibrated experimental paradigms (e.g. false-belief tasks) designed to detect the emergence of specific cognitive milestones.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-method-developmental-tasks"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['false-belief task','milestone testing']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-method-computational-modeling', 'Computational modeling', 'method', 'Formal and simulation-based models of cognitive or social-learning processes, used to generate testable predictions about developmental trajectories.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-method-computational-modeling"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['simulation','formal models']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-topic-cooperation-development', 'Cooperation development', 'topic', 'How the capacity and motivation for cooperative behavior emerges and changes across childhood, and how this trajectory varies across cultures.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-topic-cooperation-development", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-cooperation"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['prosocial development','cooperative behavior']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-topic-fairness', 'Fairness', 'topic', 'The developmental and cross-cultural emergence of fairness concerns and equitable resource distribution.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-topic-fairness"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['equity','resource sharing']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-topic-norm-acquisition', 'Norm acquisition', 'topic', 'How children come to recognize, internalize, and enforce the social norms of their community.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-topic-norm-acquisition"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['norm learning','socialization']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-topic-cultural-variation-in-cognition', 'Cultural variation in cognition', 'topic', 'The extent to which cognitive processes long assumed universal actually vary systematically across cultural contexts.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-topic-cultural-variation-in-cognition"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cross-cultural cognition','universality debate']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-topic-communication-development', 'Communication development', 'topic', 'How communicative and language capacities emerge and how their developmental trajectory relates to social cognition more broadly.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-topic-communication-development"}'::jsonb, '{"source": "eva_seed_list.py", "status": "draft", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['language emergence','communicative development']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-topic-cross-cultural-norm-enforcement', 'Cross-cultural norm enforcement in children', 'topic', 'Whether children''s willingness to intervene when a peer breaks a rule is a human universal or a culturally specific behavior — testing 5-8-year-olds across 8 diverse small-scale and large-scale societies found children everywhere enforced a novel game''s conventional rules, but the style of enforcement (imperative protest vs. rule-citing protest) varied culturally, showing the underlying motivation is universal while its expression is not.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-topic-cross-cultural-norm-enforcement"}'::jsonb, '{"source": "curator-drafted; grounded in Kanngiesser, Schäfer, Herrmann, Zeidler, Haun & Tomasello (2022, PNAS 119(2):e2112521118, doi:10.1073/pnas.2112521118, ''Children across societies enforce conventional norms but in culturally variable ways'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['norm enforcement','cross-cultural comparison','middle childhood']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-topic-cross-species-preference-inference', 'Inferring others'' preferences across species and cultures', 'topic', 'Whether anticipating a competitor''s choice from their known preferences is a distinctly human, cross-culturally recurrent capacity — children from three culturally diverse societies (Namibia, Germany, Samoa) showed this ability consistently, while four tested great-ape species (chimpanzee, bonobo, gorilla, orangutan) did not, in a direct comparative design run alongside the department''s Pan Cultures work.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-topic-cross-species-preference-inference"}'::jsonb, '{"source": "curator-drafted; grounded in Kaminski, Stengelin, Girndt, Haun & Liebal (2024, PLOS ONE 19(1):e0295221, doi:10.1371/journal.pone.0295221, ''Understanding others'' preferences: A comparison across primate species and human societies'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['preference inference','cross-species comparison','social cognition']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-topic-individual-differences-in-great-ape-cognition', 'Individual differences in great ape cognition', 'topic', 'Testing captive great apes across five cognitive tasks found individual performance was stable and repeatable over time, and predicted by each ape''s own developmental rearing conditions — establishing that within-species individual variation, not just between-species differences, structures great ape cognition, drawing on the same WKPRC infrastructure behind this dataset''s EVApeCognition fieldsite.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-topic-individual-differences-in-great-ape-cognition"}'::jsonb, '{"source": "curator-drafted; grounded in Bohn, Eckert, Hanus, Lugauer, Holtmann & Haun (2023, Nature Ecology & Evolution 7:927-938, doi:10.1038/s41559-023-02050-8, ''Great ape cognition is structured by stable cognitive abilities and predicted by developmental conditions'')", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['individual differences','great ape cognition','developmental conditions']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-scicomm-zoo-based-ape-cognition', 'Zoo-based great ape cognition research', 'scicomm-sensitivity', 'CCP''s comparative-cognition work with chimpanzees, bonobos, orangutans, and gorillas is largely conducted at zoo-based research centers rather than in the wild, which is scientifically valuable (controlled comparison, longitudinal access) but publicly legible mainly through the lens of ''apes in captivity.''', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-scicomm-zoo-based-ape-cognition"}'::jsonb, '{"source": "curator-drafted; grounded in documented zoo-based great-ape cognition research practice at MPI-EVA-affiliated facilities", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['captive research','animal welfare','zoo partnership','great apes']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-scicomm-cross-cultural-child-research', 'Cross-cultural research with children', 'scicomm-sensitivity', 'CCP''s comparative developmental work depends on running the same or comparable tasks with children from societies with very different childrearing practices, economies, and relationships to outside researchers — a design that only works, and only remains ethical, with genuine informed consent and ongoing trust from families and communities.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-scicomm-cross-cultural-child-research"}'::jsonb, '{"source": "curator-drafted; grounded in documented critiques of WEIRD-sample bias in developmental psychology (Henrich, Heine & Norenzayan 2010) and cross-cultural research-ethics practice", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['informed consent','cross-cultural comparison','child development','WEIRD bias']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('ccp-scicomm-anthropomorphism-vs-anthropodenial', 'Anthropomorphism vs. anthropodenial in reporting animal cognition', 'scicomm-sensitivity', 'CCP''s core scientific contribution is often exactly the nuanced middle ground — what a species does and doesn''t share with human cognition — but that nuance is the first thing lost in translation to a headline or exhibit caption.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "ccp-scicomm-anthropomorphism-vs-anthropodenial"}'::jsonb, '{"source": "curator-drafted; grounded in the anthropomorphism/anthropodenial framing from comparative cognition science communication literature (de Waal 1999)", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['anthropomorphism','science communication accuracy','comparative cognition']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('inst-theory-selection-and-adaptation', 'Selection and Adaptation — Genetic and Biological', 'theory', 'Selection and adaptation are, at the most general level, substrate-neutral: ''selection'' is any process by which a feature increases in frequency because of its consequences in an environment, and ''adaptation'' is any feature that evolved in a population because it contributed to fitness. This node covers the specific case where the feature under selection is heritable and genetically encoded — the instantiation four MPI-EVA departments study directly: DAG and EvoGen detect it as a genomic signature (selective sweeps, reduced diversity around a locus), HumOr reconstructs it from skeletal/dental adaptation in the fossil record, and PrimEvo studies its sexual-selection variant shaping primate mating systems. It has a companion node, inst-theory-cultural-and-behavioral-selection-and-adaptation, for the non-genetic case — behavioral, cognitive, and cultural variants selected and retained without a genetic mechanism doing the selecting — which is the primary purview of DLCE, HBEC, and CCP rather than a peripheral concern of this node''s four departments.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "inst-theory-selection-and-adaptation", "conceptBaseId": "OE-CONCEPT-bio-core-natural-selection", "departments": ["dag", "evogen", "humor", "primevo"], "scope": "institute"}'::jsonb, '{"source": "derived from mpi-eva-graph/sub-units department node overlap", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['natural selection','adaptation','sexual selection','evolutionary mechanism','genetic selection']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('inst-theory-cultural-and-behavioral-selection-and-adaptation', 'Selection and Adaptation — Cultural and Behavioral', 'theory', 'The companion case to inst-theory-selection-and-adaptation: the same general mechanism — a feature persisting or spreading because of its consequences in an environment — applied to behavioral, cognitive, and cultural variants rather than genes. HBEC''s and DLCE''s cultural-evolution theories treat cultural traits (skills, beliefs, practices, and — for DLCE specifically — linguistic and narrative forms) as undergoing variation, selection, and inheritance analogous to, but mechanistically distinct from, biological evolution; CCP''s learning-biases theory names the selective-retention mechanism itself — which models and information children preferentially copy, i.e. which variants actually get selected during transmission. None of this requires a genetic substrate: DLCE and CCP do not study genes at all, and for HBEC genetics is one contributing strand among several rather than the department''s organizing framework — unlike the four departments behind this node''s companion.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "inst-theory-cultural-and-behavioral-selection-and-adaptation", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-selection", "departments": ["hbec", "dlce", "ccp"], "scope": "institute"}'::jsonb, '{"source": "derived from mpi-eva-graph/sub-units department node overlap, added in response to direct critique of the original node''s framing", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cultural evolution','cultural selection','behavioral adaptation','learning bias','non-genetic selection']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('inst-theory-cultural-transmission-and-social-learning', 'Cultural Transmission and Social Learning', 'theory', 'The theory that behaviors, skills, and beliefs spread through populations by observation, imitation, and teaching rather than genetic inheritance alone — HBEC''s and DLCE''s own cultural-evolution and social-learning theories treat this directly, CCP studies the learning biases that shape which models and information children preferentially copy, and PrimEvo documents its behavioral signature as socially learned tool-use traditions in wild primates.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "inst-theory-cultural-transmission-and-social-learning", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-transmission", "departments": ["hbec", "dlce", "ccp", "primevo"], "scope": "institute"}'::jsonb, '{"source": "derived from mpi-eva-graph/sub-units department node overlap", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['social learning','cultural transmission','imitation','dual inheritance']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('inst-theory-life-history-theory', 'Life History Theory', 'theory', 'The evolutionary framework explaining how organisms allocate finite resources between growth, reproduction, and survival across the lifespan — applied by HBEC and PrimEvo to living human and primate populations respectively, and by HumOr to the fossil and dental evidence of how that allocation pattern itself evolved across hominin lineages.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "inst-theory-life-history-theory", "departments": ["hbec", "primevo", "humor"], "scope": "institute"}'::jsonb, '{"source": "derived from mpi-eva-graph/sub-units department node overlap", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['growth','reproduction','trade-offs','life history']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('inst-domain-population-structure-and-demography', 'Population Structure and Demography', 'domain', 'How population size, structure, and vital rates are organized and change over time. DAG and EvoGen reconstruct this from genomic variation (paleodemography, effective population size, demographic bottlenecks), HBEC studies it directly through fieldwork in living small-scale societies, and PrimEvo tracks group size, sex ratio, and age structure in wild primate populations.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "inst-domain-population-structure-and-demography", "conceptBaseId": "OE-CONCEPT-bio-core-population", "departments": ["dag", "evogen", "hbec", "primevo"], "scope": "institute"}'::jsonb, '{"source": "derived from mpi-eva-graph/sub-units department node overlap", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['demography','population size','population structure']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('inst-domain-migration-and-dispersal', 'Migration and Dispersal', 'domain', 'The movement of individuals and populations across landscapes, and its downstream social and genetic consequences. DAG reconstructs ancient human migration waves from genomic transects, HumOr traces hominin dispersal from fossil and archaeological distributions, HBEC studies residential and logistical mobility patterns in living societies, and PrimEvo studies natal dispersal''s effect on primate gene flow, social structure, and inbreeding avoidance.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "inst-domain-migration-and-dispersal", "departments": ["dag", "hbec", "humor", "primevo"], "scope": "institute"}'::jsonb, '{"source": "derived from mpi-eva-graph/sub-units department node overlap", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['migration','dispersal','mobility','gene flow']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('inst-domain-ancient-and-archaic-genomes', 'Ancient and Archaic Genomes', 'domain', 'Genomic material recovered from ancient or archaic (non-modern) hominin remains — DAG''s core ancient-DNA domain and the degraded, contaminated samples it specializes in extracting and authenticating, EvoGen''s archaic-hominin-genomes domain used for downstream population-genetic analysis, and HumOr''s paleogenomics domain that integrates that same evidence with fossil and archaeological context.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "inst-domain-ancient-and-archaic-genomes", "conceptBaseId": "OE-SANDBOX-CONCEPT-000002", "departments": ["dag", "evogen", "humor"], "scope": "institute"}'::jsonb, '{"source": "derived from mpi-eva-graph/sub-units department node overlap", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['ancient DNA','archaic hominins','paleogenomics']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('inst-method-phylogenetic-tree-based-methods', 'Phylogenetic and Tree-Based Inference Methods', 'method', 'Statistical methods that model lineages as branching trees to reconstruct relationships and divergence times. DAG and EvoGen apply this to genomic and population lineages (phylogenetics, phylogenomic analysis), DLCE applies the same Bayesian tree-inference machinery to language and cultural-trait lineages instead of genes, and HBEC applies phylogenetic comparative methods to correct for shared ancestry when statistically comparing populations or species.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "inst-method-phylogenetic-tree-based-methods", "conceptBaseId": "OE-CONCEPT-bio-core-phylogeny", "departments": ["dag", "evogen", "dlce", "hbec"], "scope": "institute"}'::jsonb, '{"source": "derived from mpi-eva-graph/sub-units department node overlap", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['phylogenetics','tree inference','Bayesian methods','divergence dating']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('inst-topic-cooperation-and-fairness', 'Cooperation and Fairness', 'topic', 'Open questions about why individuals cooperate and how norms of fair exchange emerge and are enforced. HBEC''s largest single topic cluster (cooperation, fairness, punishment, partner choice) studies this in living human societies; PrimEvo studies its coalition- and alliance-formation precursors in wild primates; CCP studies when and how children acquire cooperative behavior and fairness concerns developmentally and cross-culturally.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "inst-topic-cooperation-and-fairness", "conceptBaseId": "OE-CONCEPT-oe-interdisciplinary-cooperation", "departments": ["hbec", "primevo", "ccp"], "scope": "institute"}'::jsonb, '{"source": "derived from mpi-eva-graph/sub-units department node overlap", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cooperation','fairness','norms','prosociality']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('inst-topic-archaic-introgression', 'Archaic Introgression', 'topic', 'The open question of how much, when, and with what functional consequences anatomically modern humans interbred with archaic hominins such as Neanderthals and Denisovans. DAG studies it through admixture modeling and Neanderthal-admixture case work, EvoGen through genomic analysis of the functional and phenotypic consequences of introgressed variants persisting today, and HumOr through the fossil and genomic biology of the archaic populations themselves.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "inst-topic-archaic-introgression", "departments": ["dag", "evogen", "humor"], "scope": "institute"}'::jsonb, '{"source": "derived from mpi-eva-graph/sub-units department node overlap", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Neanderthal','Denisovan','introgression','admixture']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('inst-scicomm-animal-research-and-public-perception', 'Animal research and public perception', 'scicomm-sensitivity', 'CCP''s comparative cognition work is largely zoo-based (Leipzig Zoo''s Wolfgang Köhler Primate Research Center); PrimEvo combines wild-population field observation with some captive-facility and non-invasive sampling work; EvoGen functionally validates human-evolutionary genetic variants in mouse models. All three require the same basic communication discipline: name the animal, the facility or field context, the welfare oversight, and the specific method, rather than either hiding the animal-research component or over-dramatizing it.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "inst-scicomm-animal-research-and-public-perception", "departments": ["ccp", "primevo", "evogen"], "scope": "institute"}'::jsonb, '{"source": "derived from mpi-eva-graph/sub-units department scicomm_sensitivities.json overlap", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['animal research','animal welfare','public perception','captive research']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('inst-scicomm-human-remains-and-repatriation', 'Human remains, fossils, and repatriation', 'scicomm-sensitivity', 'DAG''s version centers on ancient-DNA sampling of skeletal remains and the field-wide 2021 guidance on responsible ancient-human-remains research; HumOr''s centers on fossil collections with colonial-era acquisition histories and the need for genuine host-country research partnership. Different material (genetic material vs. fossil specimens), same underlying obligation: name the consultation, consent, or partnership process whenever findings from remains are communicated publicly.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "inst-scicomm-human-remains-and-repatriation", "departments": ["dag", "humor"], "scope": "institute"}'::jsonb, '{"source": "derived from mpi-eva-graph/sub-units department scicomm_sensitivities.json overlap", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['human remains','repatriation','ancient DNA','fossil collections','indigenous rights']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('inst-scicomm-oversimplified-genetic-narratives', 'Oversimplified evolutionary and genetic narratives', 'scicomm-sensitivity', 'DAG and EvoGen both generate the ''percent Neanderthal'' oversimplification from different methods (demographic admixture modeling vs. functional genomics); EvoGen''s disease-variant findings and DAG''s population-structure findings both risk genetic-determinist and racialized misreadings; HumOr''s fossil record is popularly flattened into linear ''March of Progress'' narratives that misrepresent its actual branching structure. All three call for the same discipline: lead public communication with the specific mechanism and its demographic or evolutionary explanation, not an aggregate statistic or a single-line narrative.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "inst-scicomm-oversimplified-genetic-narratives", "departments": ["dag", "evogen", "humor"], "scope": "institute"}'::jsonb, '{"source": "derived from mpi-eva-graph/sub-units department scicomm_sensitivities.json overlap", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['genetic determinism','public narratives','media coverage','race and genetics']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('inst-scicomm-community-consent-and-benefit-sharing', 'Community consent and benefit-sharing in research with living communities', 'scicomm-sensitivity', 'HBEC''s hunter-gatherer and small-scale-society fieldwork, DLCE''s endangered-language documentation, CCP''s cross-cultural child research, PrimEvo''s field sites in primate range countries, and EvoGen''s diverse genomic sample panels are methodologically very different, but each depends on a research relationship with a specific community that has, across the wider field''s history, sometimes been extractive rather than reciprocal. The most natural institute-wide sensitivity in this dataset — it is the only scicomm theme that reaches a genuine majority of departments (5 of 7) rather than a tight 2–3-department cluster.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "inst-scicomm-community-consent-and-benefit-sharing", "departments": ["hbec", "dlce", "ccp", "primevo", "evogen"], "scope": "institute"}'::jsonb, '{"source": "derived from mpi-eva-graph/sub-units department scicomm_sensitivities.json overlap", "status": "draft", "created": "2026-08-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['informed consent','reciprocity','benefit-sharing','community partnership','fieldwork ethics']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-denisova-cave', 'Denisova Cave', 'fieldsite', 'The single cave where a 2010 finger-bone DNA analysis revealed the Denisovans, a previously unknown archaic hominin lineage — the founding discovery of MPI-EVA''s paleogenomics program and still an active dual-department excavation/sequencing site.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "fieldsite-denisova-cave", "departments": ["evogen", "dag"]}'::jsonb, '{"source": "whc.unesco.org/en/tentativelists/6625/, eva.mpg.de/press/news/2021/2021-06-23-1346-pleistocene-sediment-dna-from-denisova-cave/, nature.com/articles/nature08976", "status": "draft", "created": "2026-09-01", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['ancient DNA','Denisovans','paleogenomics','archaic hominins']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-vindija-cave', 'Vindija Cave', 'fieldsite', 'Source cave of the high-coverage Neandertal genome (sequenced from a bone found in 1980) that let MPI-EVA researchers identify additional Neandertal ancestry in present-day non-African populations.', (select id from kgdj.departments where code = 'evogen'), 'proposed', '{"meg": "fieldsite-vindija-cave"}'::jsonb, '{"source": "mpg.de/11515535/neandertaler-genome-croatia, eva.mpg.de/genetics/genome-projects/neandertal/draft-neandertal-genome/data, science.org/doi/10.1126/science.aao1887", "status": "draft", "created": "2026-09-01", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['ancient DNA','Neanderthal','paleogenomics','reference genome']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-issyk-kurgan', 'Issyk Kurgan', 'fieldsite', 'One of ~45 royal kurgans at this Iron Age Saka burial ground, excavated since 1969 and famous for the ''Golden Man'' warrior burial (c. 400–300 BCE) — the site of the first genome-wide ancient-DNA data from that individual, generated as part of a 2026 DAG study finding political power passed through elite family lineages across Eurasian steppe burial sites.', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "fieldsite-issyk-kurgan"}'::jsonb, '{"source": "pmc.ncbi.nlm.nih.gov/articles/PMC13330900/ (fetched directly), doi.org/10.1126/sciadv.aef0108, eurekalert.org/news-releases/1133788, en.wikipedia.org/wiki/Issyk_kurgan", "status": "draft", "created": "2026-09-02", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['ancient DNA','Scythian','Saka','Iron Age','steppe nomads','kinship']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-jebel-irhoud', 'Jebel Irhoud', 'fieldsite', 'Site of fossils redated in 2017 to ~300,000 years ago — by far the oldest securely dated Homo sapiens remains known, pushing the species'' origin back roughly 100,000 years and reframing it as a pan-African rather than single-region event.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "fieldsite-jebel-irhoud"}'::jsonb, '{"source": "mpg.de/11322481/oldest-homo-sapiens-fossils-at-jebel-irhoud-morocco, nature.com/articles/nature22336, latitude.to/articles-by-country/ma/morocco/78084/jebel-irhoud", "status": "draft", "created": "2026-09-01", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['paleoanthropology','Homo sapiens origins','fossil hominins']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-thomas-quarry-casablanca', 'Thomas Quarry I', 'fieldsite', 'Cave-complex quarry site on Casablanca''s Atlantic littoral, part of an internationally important Plio-Pleistocene coastal archive — a 2026 study redated hominin fossils here (alongside sister site Oulad Hamida) to ~773,000 years, among the oldest well-dated hominin remains in North Africa.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "fieldsite-thomas-quarry-casablanca"}'::jsonb, '{"source": "nature.com/articles/s41586-025-09914-y, natureasia.com/en/info/press-releases/detail/9199, sciencedaily.com/releases/2026/02/260206012221.htm, mindat.org/paleo_loc.php?id=31082 (coordinates)", "status": "draft", "created": "2026-09-02", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['paleoanthropology','fossil hominins','Acheulean','North Africa','chronostratigraphy']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-tai-national-park', 'Taï National Park', 'fieldsite', 'MPI-EVA''s flagship wild-chimpanzee field site, continuously studied since 1979 — the source of foundational findings on wild chimpanzee tool use and tool making, still an active multi-camp research station, today organizationally part of HBEC (Crockford & Wittig) though its findings remain PrimEvo''s natural conceptual domain.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "fieldsite-tai-national-park", "departments": ["hbec", "primevo"]}'::jsonb, '{"source": "en.wikipedia.org/wiki/Taï_National_Park, latlong.net Taï National Park entry, eva.mpg.de/fileadmin/content_files/staff/boesch/pdf/pan_af_new_tai_chimp_proj.pdf, karger.com Folia Primatologica 54(1-2)", "status": "draft", "created": "2026-09-01", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['primatology','chimpanzees','tool use','long-term field site']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-amboseli', 'Amboseli National Park', 'fieldsite', 'Site of the Amboseli Baboon Research Project, a continuous, individual-based study of wild yellow/anubis-hybrid baboons founded by Stuart and Jeanne Altmann in 1971 — life-history data on 1,500+ known individuals across five decades, still monitoring roughly 300 animals near-daily today.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "fieldsite-amboseli"}'::jsonb, '{"source": "en.wikipedia.org/wiki/Amboseli_Baboon_Research_Project, amboselibaboons.nd.edu/about-the-project/, link.springer.com/chapter/10.1007/978-3-642-22514-7_12, this repo''s own assets/PrimEvo/amboselli-pedigree/manifest.json", "status": "draft", "created": "2026-09-02", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['primatology','baboons','long-term field site','pedigree genetics','life-history data']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-pemba-island', 'Pemba Island', 'fieldsite', 'Long-running (since 2015) HBEC field site studying community-based resource-management institutions, household economic adaptation, and tropical coastal-ecosystem conservation, including REDD+ forest-carbon program evaluation.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "fieldsite-pemba-island"}'::jsonb, '{"source": "eva.mpg.de/ecology/fieldwork/pemba.html, cambridge.org Oryx article page, en.wikipedia.org/wiki/Pemba_Island", "status": "draft", "created": "2026-09-01", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['behavioral ecology','institutions','REDD+','conservation','long-term field site']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-motaba-river-bayaka', 'Motaba River (BaYaka research camp)', 'fieldsite', 'A Motaba River BaYaka/Bandongo research area studied by two MPI-EVA departments: HBEC''s own work on collaborative foraging and childcare/subsistence trade-offs (this node''s primary research_output), and CCP''s separate study of children''s sharing-norm development — HBEC''s second real field site alongside Pemba, added specifically as the example this repo''s fieldsites/README.md had already flagged as its next natural addition; the CCP connection surfaced afterward while checking whether CCP had its own genuine Congo Basin presence.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "fieldsite-motaba-river-bayaka", "departments": ["hbec", "ccp"]}'::jsonb, '{"source": "pmc.ncbi.nlm.nih.gov/articles/PMC9667358/ (fetched directly), doi.org/10.1098/rspb.2022.1407, doi.org/10.1371/journal.pone.0276845, en.wikipedia.org/wiki/Dongou, en.wikipedia.org/wiki/Motaba", "status": "draft", "created": "2026-09-02", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['BaYaka','hunter-gatherers','childcare','collaborative foraging','sharing norms','cross-cultural cognition','long-term field site']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-emae-island-vanuatu', 'Emae Island', 'fieldsite', 'One of four small-scale multilingualism case-study sites (alongside North Malekula and Maewo Island) documented by MPI-EVA''s Comparative Oceanic Linguistics group across Vanuatu''s 65 inhabited islands, each with its own distinct linguistic ecology.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "fieldsite-emae-island-vanuatu"}'::jsonb, '{"source": "journals.sagepub.com/doi/10.1177/13670069211023132, eva.mpg.de/linguistic-and-cultural-evolution/research/cool/, latitude.to Emae Vanuatu entry", "status": "draft", "created": "2026-09-01", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['language documentation','multilingualism','Oceanic languages','Vanuatu']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-maewo-vanuatu', 'Maewo Island', 'fieldsite', 'One of the study''s four small-scale multilingualism case-study sites — Maewo (Penama Province, ~1,400 speakers of Sungwadaga/Central Maewo per Ethnologue-derived sources) is linguistically and ecologically distinct from Emae''s Shepherd Islands setting, part of what makes the four-site comparison meaningful.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "fieldsite-maewo-vanuatu"}'::jsonb, '{"source": "journals.sagepub.com/doi/10.1177/13670069211023132, en.wikipedia.org/wiki/Maewo, en.wikipedia.org/wiki/Sungwadaga_language", "status": "draft", "created": "2026-09-02", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['language documentation','multilingualism','Oceanic languages','Vanuatu']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-north-malekula-vanuatu', 'North Malekula', 'fieldsite', 'One of the study''s four small-scale multilingualism case-study sites — north Malekula is one of the most linguistically dense areas in Vanuatu (itself one of the world''s most linguistically dense countries), with numerous small, distinct language communities packed into a small geographic area.', (select id from kgdj.departments where code = 'dlce'), 'proposed', '{"meg": "fieldsite-north-malekula-vanuatu"}'::jsonb, '{"source": "journals.sagepub.com/doi/10.1177/13670069211023132, en.wikipedia.org/wiki/Malakula, en.wikipedia.org/wiki/Wala_(island), en.wikipedia.org/wiki/Botovro_language", "status": "draft", "created": "2026-09-02", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['language documentation','multilingualism','Oceanic languages','Vanuatu']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-wkprc-leipzig-zoo', 'Wolfgang Köhler Primate Research Center', 'fieldsite', 'MPI-EVA''s captive great-ape cognition testing facility at Leipzig Zoo, source of EVApeCognition — an 18-year (2004–2021), 246-study, 105-named-participant open dataset spanning chimpanzees, bonobos, gorillas, and orangutans, described on its 2026 publication as the largest open dataset of great ape cognition in existence. This repo''s own assets/CCP/evape-cognition-oecs/ mirrors a curated slice of it, and js/evape-db-explorer.js is a live whiteboard artifact built directly on that data.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "fieldsite-wkprc-leipzig-zoo"}'::jsonb, '{"source": "mpg.de/26395591/largest-open-dataset-of-great-ape-cognition-released, eurekalert.org/news-releases/1125110, eva.mpg.de/comparative-cultural-psychology/studying-non-human-primates/wolfgang-koehler-primate-research-center/, this repo''s own assets/CCP/evape-cognition-oecs/manifest.json and processed/evapecognition-db-explorer.json", "status": "draft", "created": "2026-09-02", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['great ape cognition','comparative cognition','captive research','open dataset','theory of mind']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-ranis-germany', 'Ilsenhöhle, Ranis', 'fieldsite', 'A rock shelter beneath Ranis Castle where ~45,000-year-old modern human remains were recovered and sequenced, constraining the timing of the single major Neanderthal admixture pulse into non-African populations to roughly 45,000-49,000 years ago, over a window estimated at about 7,000 years. A companion 2024 paper (McPherron, Hublin et al.) separately attributed the site''s LRJ stone-tool assemblage to these same H. sapiens, one of the earliest secure H. sapiens presences at high European latitudes.', (select id from kgdj.departments where code = null), 'proposed', '{"meg": "fieldsite-ranis-germany", "departments": ["evogen", "dag", "humor"]}'::jsonb, '{"source": "nature.com/articles/s41586-024-08420-x; nature.com/articles/s41586-023-06923-7; general-knowledge placement of Ranis, Thuringia — not independently verified against site-specific geodata in this pass", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['ancient DNA','Neanderthal admixture','modern human origins','Ranis','stone tools','LRJ']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-swartkrans-south-africa', 'Swartkrans', 'fieldsite', 'A cave site in South Africa''s Cradle of Humankind where a rare, directly associated hip bone, femur, and tibia of a small adult Paranthropus robustus (c. 1.7 million years old) were described in 2025 — new direct evidence for this species'' posture and gait, distinct from the locomotor pattern already documented for Australopithecus at nearby Sterkfontein.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "fieldsite-swartkrans-south-africa"}'::jsonb, '{"source": "doi.org/10.1016/j.jhevol.2024.103647; general-knowledge placement of Swartkrans — not independently verified against site-specific geodata in this pass", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Paranthropus robustus','Cradle of Humankind','postcranial anatomy','locomotion']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-kara-djigach-kyrgyzstan', 'Kara-Djigach cemetery', 'fieldsite', 'One of two 1338-1339 CE Chüy Valley cemeteries (with sister site Burana) where ancient DNA from plague victims identified a Yersinia pestis strain genetically ancestral to the Black Death''s explosive 14th-century diversification — pinpointing Central Asia, not the Black Sea/Crimea, as the pandemic''s geographic source. Directly grounds Johannes Krause''s 2026 Leibniz Prize citation for ''an evidence-based understanding of the history of epidemics.''', (select id from kgdj.departments where code = 'dag'), 'proposed', '{"meg": "fieldsite-kara-djigach-kyrgyzstan"}'::jsonb, '{"source": "nature.com/articles/s41586-022-04800-3; general-knowledge placement of the Chüy Valley — not independently verified against site-specific geodata in this pass", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Yersinia pestis','Black Death','paleoepidemiology','medieval Central Asia']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-inuvialuit-settlement-region-canada', 'Inuvialuit Settlement Region', 'fieldsite', 'A real, current HBEC field site (the Sanguatsiniq Research Project) studying Inuit subsistence harvesting, foraging, and carbon economics in Canada''s western Arctic — Bayesian estimation shows local harvesting is substantially more carbon-efficient than market-food substitutes, direct evidence for how Indigenous subsistence economies interact with encroaching market and carbon economies.', (select id from kgdj.departments where code = 'hbec'), 'proposed', '{"meg": "fieldsite-inuvialuit-settlement-region-canada"}'::jsonb, '{"source": "doi.org/10.1073/pnas.2317686121; eva.mpg.de/ecology/projects-and-research-groups/; general-knowledge placement of the Inuvialuit Settlement Region — not independently verified against site-specific geodata in this pass", "status": "draft", "created": "2026-09-03", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Inuit','Arctic','subsistence economy','carbon economy','Sanguatsiniq']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-rising-star-cave-south-africa', 'Rising Star Cave System (Dinaledi Chamber)', 'fieldsite', 'A deep, extremely hard-to-access chamber (the Dinaledi Chamber) within the Rising Star Cave System where over 1,550 fossil elements of Homo naledi — a small-brained, mosaic-anatomy hominin combining primitive and derived traits, including notably dexterous hands — were recovered starting in 2013, named and described in 2015.', (select id from kgdj.departments where code = 'humor'), 'proposed', '{"meg": "fieldsite-rising-star-cave-south-africa"}'::jsonb, '{"source": "elifesciences.org/articles/09560 (DOI Crossref-verified 2026-09-04); general-knowledge placement of the Rising Star Cave System — not independently verified against site-specific geodata in this pass", "status": "draft", "created": "2026-09-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['Homo naledi','hand morphology','manual dexterity','Cradle of Humankind']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-bili-uele-drc', 'Bili-Uélé Forest', 'fieldsite', 'A vast (~50,000 km² surveyed, within a ~78,000 km² protected-area complex), remote forest region in northern DRC where a large, continuous population of several thousand Eastern chimpanzees (Pan troglodytes schweinfurthii) was documented — a PanAf field site distinctive for a rich, unusual toolkit (large termite-fishing tools, nut-cracking, possible ant-dipping wands) and the accumulative stone-throwing behavior first recorded here alongside other West/Central African sites.', (select id from kgdj.departments where code = 'primevo'), 'proposed', '{"meg": "fieldsite-bili-uele-drc"}'::jsonb, '{"source": "doi.org/10.1159/000492998 (Crossref-verified 2026-09-04); en.wikipedia.org/wiki/Bili_Forest (coordinates); mpg.de/7896302/chimpanzee_population_congo", "status": "draft", "created": "2026-09-04", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['PanAf','Chimp&See','chimpanzees','tool use','camera trap','remote forest']::text[]) on conflict (slug) do nothing;
insert into kgdj.nodes (slug, label, type_code, description, department_id, status, external_ids, provenance, tags) values ('fieldsite-oshikoto-namibia', 'Oshikoto Region (Akhoe Haiǁom communities)', 'fieldsite', 'Field site for cross-cultural cognitive-science research with the Akhoe Haiǁom, a semi-nomadic hunter-gatherer community in northern Namibia whose language encodes spatial relations very differently from German/English — the basis for an early, influential MPI-EVA line of research on how culture and language shape memory and spatial cognition.', (select id from kgdj.departments where code = 'ccp'), 'proposed', '{"meg": "fieldsite-oshikoto-namibia"}'::jsonb, '{"source": "eva.mpg.de/documents/Elsevier/Haun_Variation_CurrBiol_2009_1554168.pdf (fetched and read directly 2026-09-04, acknowledgments section), open-web search placing Khomxa Khoeda Junior Primary School and Farm Six in Mangetti West near Tsumeb, en.wikipedia.org/wiki/ǂAakhoe_dialect, sciencedirect.com/science/article/pii/S0960982209018983, eva.mpg.de/comparative-cultural-psychology/staff/daniel-haun/", "status": "draft", "created": "2026-09-01", "imported_from": "eva-graph/mpi-eva-graph", "imported_at": "2026-09-04", "assigned_by": "curator", "import_note": "single-pass curator draft; enters the journal as proposed"}'::jsonb, array['cross-cultural cognition','spatial cognition','hunter-gatherers','Akhoe Haiǁom']::text[]) on conflict (slug) do nothing;
